export default [
  {"m": "Qué es Python", "t": "Qué es Python", "x": "Lenguaje de programación sencillo, legible y muy versátil.\n\nPython se creó en 1991 con la idea de que el código se lea casi como inglés. Es uno de los lenguajes más populares del mundo y el favorito para empezar. Se usa en páginas web, análisis de datos, automatización, videojuegos e inteligencia artificial.", "u": "Programar desde cosas simples hasta inteligencia artificial.\n\nBuscas un lenguaje fácil de leer para empezar a programar y que luego sirva para muchas cosas.", "p": ["Python es un lenguaje de programación fácil de leer.", "Se usa en web, datos, automatización e inteligencia artificial.", "Es muy recomendado para empezar a programar."], "c": "# Un programa en Python se lee casi como una frase\nnombre = \"Ana\"\nprint(\"Hola,\", nombre)\nprint(\"Python es fácil de leer\")", "h": "Guarda un nombre y muestra dos mensajes.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El lenguaje que se lee casi como inglés y es ideal para empezar es ___. (6 letras)", "e": "Creer que Python solo sirve para principiantes."},
  {"m": "Qué es Python", "t": "Para qué sirve Python", "x": "Repaso de los campos donde se usa Python hoy.\n\nCon Python se analizan datos (pandas), se crean sitios web (Django, Flask), se automatizan tareas aburridas, se programan robots y se entrenan modelos de inteligencia artificial. Empresas como Google, Netflix o Instagram lo usan.", "u": "Saber qué puedes construir con lo que aprendas.\n\nTe preguntas si Python sirve para crear sitios web, analizar datos y automatizar tareas.", "p": ["Python se usa para analizar datos y crear sitios web.", "Se puede usar para automatizar tareas repetitivas.", "Grandes empresas usan Python."], "c": "usos = [\"análisis de datos\", \"sitios web\", \"automatización\", \"inteligencia artificial\"]\nprint(\"Con Python puedes hacer:\")\nfor uso in usos:\n    print(\"-\", uso)", "h": "Lista cuatro usos de Python recorriendo una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una librería muy usada de Python para analizar datos es ___. (6 letras)", "e": "Pensar que Python solo sirve para hacer scripts pequeños."},
  {"m": "Qué es Python", "t": "Lenguaje interpretado", "x": "Lenguaje que se ejecuta línea a línea sin compilar antes.\n\nPython lee y ejecuta tu código instrucción por instrucción mediante un intérprete. Puedes escribir una línea y ver el resultado al momento, algo ideal para aprender. A cambio, suele ser más lento que lenguajes compilados como C.", "u": "Probar código rápido y ver errores al instante.\n\nQuieres escribir una línea de código y ver su resultado al instante sin compilar nada.", "p": ["Python ejecuta el código línea a línea con un intérprete.", "No hace falta compilar antes de ejecutar.", "Suele ser más lento que los lenguajes compilados."], "c": "print(\"Primera línea: se ejecuta al momento\")\nprint(2 + 3)\nprint(\"El intérprete va leyendo línea a línea\")", "h": "Ejecuta tres líneas una tras otra sin compilar.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El programa que lee y ejecuta tu código Python se llama ___. (11 letras)", "e": "Creer que hay que compilar un programa Python antes de correrlo."},
  {"m": "Qué es Python", "t": "Python 3", "x": "Versión actual y única recomendada del lenguaje.\n\nPython 2 dejó de recibir soporte en 2020. Hoy todo se hace con Python 3 (3.12 o superior). Si un tutorial usa print \"hola\" sin paréntesis, es de Python 2 y no funcionará. Para ver tu versión: python --version.", "u": "Saber qué versión usar y evitar tutoriales antiguos.\n\nUn tutorial usa print \"hola\" sin paréntesis y te da error.", "p": ["Hoy se usa Python 3.", "Python 2 dejó de tener soporte en 2020.", "En Python 3, print lleva paréntesis."], "c": "import sys\nprint(sys.version_info.major >= 3)     # True: estamos en Python 3\nprint(\"print lleva paréntesis en Python 3\")", "h": "Comprueba que se está usando Python 3.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La versión de Python que se usa hoy es la ___. (un número)", "e": "Seguir tutoriales de Python 2 con print sin paréntesis. En Python 3, print es una función y lleva paréntesis: print(\"Adiós\")."},
  {"m": "Qué es Python", "t": "Instalar Python", "x": "Proceso de poner el intérprete de Python en tu computadora.\n\nSe descarga de python.org. En Windows, marca la casilla «Add Python to PATH» al instalar; así podrás usar python desde cualquier carpeta. Al terminar, comprueba con python --version (o python3 --version en Mac y Linux).", "u": "Poder ejecutar programas Python en tu equipo.\n\nQuieres poder ejecutar Python desde cualquier carpeta de tu computadora en Windows.", "p": ["Python se descarga desde python.org.", "En Windows conviene marcar «Add Python to PATH».", "python --version comprueba la instalación."], "c": "# En la terminal (no es código Python):\n#   python --version\n# Si todo va bien muestra algo como: Python 3.12.2\nimport platform\nprint(\"Versión instalada:\", platform.python_version())", "h": "Muestra la versión de Python instalada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La página oficial para descargar Python es python.___. (3 letras)", "e": "Olvidar marcar PATH y no poder ejecutar python desde la terminal."},
  {"m": "Qué es Python", "t": "La terminal y el REPL", "x": "Entornos donde escribes y ejecutas Python directamente.\n\nSi escribes python en la terminal, entras al REPL (Read-Eval-Print Loop): escribes una instrucción, Python la evalúa e imprime el resultado. Se reconoce por el símbolo >>>. Se sale con exit() o Ctrl+Z / Ctrl+D.", "u": "Probar ideas rápido sin crear archivos.\n\nQuieres probar una operación suelta escribiéndola y viendo el resultado al instante, sin crear un archivo.", "p": ["El REPL ejecuta una instrucción y muestra su resultado.", "Se reconoce por el símbolo >>>.", "Se sale con exit()."], "c": "# En el REPL verías:\n# >>> 2 + 3\n# 5\n# >>> \"hola\".upper()\n# 'HOLA'\nprint(2 + 3)\nprint(\"hola\".upper())", "h": "Reproduce dos operaciones que probarías en el REPL.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El símbolo que muestra el REPL de Python es ___. (3 caracteres)", "e": "Guardar código largo en el REPL en lugar de un archivo."},
  {"m": "Qué es Python", "t": "Tu primer programa con print", "x": "Programa que muestra un mensaje en pantalla.\n\nprint() muestra en pantalla lo que le pases: textos entre comillas, números o varios valores separados por comas. Después de cada print, Python salta de línea. Es tu herramienta principal para ver qué hace tu programa.", "u": "Ver resultados y comprobar que funciona el código.\n\nQuieres mostrar «Hola, mundo» en pantalla.", "p": ["print() muestra información en pantalla.", "Los textos van entre comillas.", "Se pueden mostrar varios valores separados por comas."], "c": "print(\"Hola, mundo\")\nprint(\"Tengo\", 20, \"años\")        # varios valores separados por comas\nprint(7 * 6)                      # también resultados de operaciones", "h": "Muestra un saludo, una frase con un número y un cálculo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que muestra algo en pantalla es ___(). (5 letras)", "e": "Olvidar las comillas del texto. Falta poner comillas: print(\"Adiós\")."},
  {"m": "Qué es Python", "t": "Archivo .py", "x": "Archivo de texto con código Python que termina en .py.\n\nCreas un archivo, por ejemplo hola.py, escribes tu código y lo guardas. En la terminal ejecutas python hola.py desde su carpeta. Python ejecuta el archivo de arriba abajo. Los nombres de archivo no deben llevar espacios ni empezar por números.", "u": "Guardar un programa y ejecutarlo cuando quieras.\n\nQuieres guardar tu programa en un archivo y ejecutarlo cuando quieras.", "p": ["Un archivo Python termina en .py.", "Se ejecuta con python nombre.py.", "Python ejecuta el archivo de arriba abajo."], "c": "# Guarda esto como hola.py y ejecútalo con:  python hola.py\nprint(\"Estoy dentro de un archivo .py\")\nprint(\"Python ejecuta de arriba abajo\")", "h": "Muestra dos mensajes pensados para guardarse en hola.py.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un archivo de Python termina en ___. (3 caracteres con punto)", "e": "Guardar el archivo como .txt."},
  {"m": "Qué es Python", "t": "Comentarios en Python", "x": "Notas que empiezan con # y que Python ignora.\n\nTodo lo que sigue a # en una línea se ignora. Los comentarios explican el porqué del código, no lo evidente. También puedes comentar una línea para desactivarla mientras pruebas. Los textos de varias líneas con triple comilla se usan como documentación (docstrings).", "u": "Explicar el código y desactivar líneas.\n\nQuieres dejar una nota en el código que Python no ejecute.", "p": ["Los comentarios empiezan con #.", "Python ignora los comentarios.", "Un comentario debería explicar el porqué del código."], "c": "# Esto es un comentario: Python lo ignora\nprint(\"Esto sí se ejecuta\")     # también se puede comentar al final de una línea\n# print(\"Esta línea está desactivada\")", "h": "Deja notas que se ignoran y una línea desactivada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los comentarios en Python empiezan con el símbolo ___. (un carácter)", "e": "Usar // como comentario como en otros lenguajes. En Python los comentarios empiezan con #, no con //."},
  {"m": "Qué es Python", "t": "Indentación", "x": "Sangría que indica qué líneas pertenecen a un bloque.\n\nEn Python, los bloques (if, for, def) se marcan con sangría de 4 espacios en lugar de llaves. Si la sangría es incorrecta, Python da IndentationError. Todas las líneas de un mismo bloque deben tener la misma sangría. No mezcles tabuladores y espacios.", "u": "Estructurar el código: la sangría es parte de la sintaxis.\n\nQuieres indicar qué líneas pertenecen al interior de un if.", "p": ["En Python, la sangría define los bloques de código.", "La convención es usar 4 espacios.", "Una sangría incorrecta provoca IndentationError."], "c": "edad = 20\nif edad >= 18:\n    print(\"Eres mayor de edad\")      # sangría de 4 espacios: dentro del if\n    print(\"Puedes votar\")            # también dentro\nprint(\"Esto se ejecuta siempre\")     # sin sangría: fuera del if", "h": "Usa sangría para separar lo que va dentro del if de lo que va fuera.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La convención de sangría en Python es ___ espacios. (un número)", "e": "Mezclar tabuladores y espacios. Falta la sangría: la línea dentro del if debe llevar 4 espacios."},
  {"m": "Qué es Python", "t": "Código legible", "x": "Estilo de escribir código claro, como pide el Zen de Python.\n\nEl Zen de Python (import this) resume la filosofía: «Legible cuenta», «Simple es mejor que complejo», «Explícito es mejor que implícito». Escribir pensando en quien leerá el código es tan importante como que funcione.", "u": "Que otras personas (y tú mañana) entiendan tu programa.\n\nQuieres entender la filosofía de Python resumida en frases como «Simple es mejor que complejo».", "p": ["La legibilidad es un valor central en Python.", "Simple es mejor que complejo.", "Se programa pensando en quien leerá el código."], "c": "# Compara: ¿cuál se entiende mejor?\nt = 20 * 0.21 + 20                       # difícil de entender\nprecio = 20\niva = precio * 0.21                      # claro: se entiende cada paso\ntotal = precio + iva\nprint(total)", "h": "Compara un cálculo confuso con otro claro paso a paso.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para ver la filosofía de Python se escribe import ___. (4 letras)", "e": "Escribir código muy corto pero imposible de entender."},
  {"m": "Qué es Python", "t": "Qué es una variable en Python", "x": "Nombre que apunta a un valor guardado en memoria.\n\nEn Python creas una variable simplemente asignándole un valor con =, sin declarar su tipo. nombre = \"Ana\" crea la variable y apunta al texto «Ana». Puedes volver a asignarle otro valor, incluso de otro tipo. Las irás usando en toda la etapa siguiente.", "u": "Recordar datos para usarlos más tarde.\n\nQuieres guardar la edad de alguien para usarla en varios sitios del programa.", "p": ["Una variable se crea asignándole un valor con =.", "No hace falta declarar el tipo.", "El valor de una variable puede cambiar."], "c": "edad = 20                # se crea al asignar\nprint(edad)\nedad = 21                # se puede cambiar\nprint(edad)\nedad = \"veintiuno\"       # incluso a otro tipo (no siempre recomendable)\nprint(edad)", "h": "Crea una variable y cambia su valor, incluso de tipo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El símbolo que asigna un valor a una variable es ___. (un carácter)", "e": "Usar un nombre de variable antes de asignarle valor."},
  {"m": "Qué es Python", "t": "Qué es un tipo de dato en Python", "x": "Clase de valor: texto, entero, decimal o booleano.\n\nLos tipos básicos son str (texto), int (entero), float (decimal) y bool (True o False). La función type() dice de qué tipo es un valor. Cada tipo permite operaciones distintas: se puede sumar 2 + 3, y también unir textos con +, pero no sumar un texto con un número.", "u": "Saber qué operaciones se pueden hacer con cada dato.\n\nQuieres saber si el valor de una variable es un texto, un entero o un decimal.", "p": ["Los tipos básicos son str, int, float y bool.", "type() devuelve el tipo de un valor.", "No se puede sumar un texto con un número directamente."], "c": "print(type(\"hola\"))      # <class 'str'>\nprint(type(42))          # <class 'int'>\nprint(type(3.14))        # <class 'float'>\nprint(type(True))        # <class 'bool'>", "h": "Muestra el tipo de cuatro valores distintos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que devuelve el tipo de un valor es ___(). (4 letras)", "e": "Intentar sumar un texto con un número."},
  {"m": "Qué es Python", "t": "Qué es una función en Python", "x": "Bloque de código con nombre que se ejecuta al llamarlo.\n\nSe define con la palabra def y se ejecuta escribiendo su nombre con paréntesis. Puede recibir datos y devolver un resultado. print() y len() son funciones que ya trae Python; tú crearás las tuyas. Las verás en detalle en la etapa 3.", "u": "No repetir código y organizar el programa.\n\nQuieres agrupar tres líneas de código bajo un nombre para usarlas varias veces.", "p": ["Una función se define con def.", "Se ejecuta escribiendo su nombre con paréntesis.", "Python incluye muchas funciones ya hechas."], "c": "def saludar():\n    print(\"¡Hola!\")\n    print(\"Bienvenida a Python\")\n\nsaludar()        # primera llamada\nsaludar()        # segunda llamada", "h": "Define un saludo una vez y lo ejecuta dos veces.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que define una función en Python es ___. (3 letras)", "e": "Definir la función y olvidar llamarla."},
  {"m": "Qué es Python", "t": "Módulos y librerías", "x": "Archivos de código listos para importar y reutilizar.\n\nimport math trae el módulo math con funciones matemáticas (math.sqrt). Python incluye una gran «biblioteca estándar»: random, datetime, json, os… Además existen miles de librerías de terceros (requests, pandas). Con import accedes a todas.", "u": "Usar funciones ya hechas sin escribirlas.\n\nQuieres usar funciones matemáticas ya hechas, como la raíz cuadrada.", "p": ["import trae un módulo para usar sus funciones.", "Python incluye una biblioteca estándar muy completa.", "Existen miles de librerías de terceros."], "c": "import math\nprint(math.sqrt(16))        # 4.0\nprint(math.pi)              # 3.14159...\nimport random\nprint(random.randint(1, 1))  # número entero entre 1 y 1 (siempre 1)", "h": "Importa dos módulos y usa algunas de sus funciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que trae un módulo es ___. (6 letras)", "e": "Usar math.sqrt sin importar antes math. Hay que importar math antes de usarlo."},
  {"m": "Qué es Python", "t": "pip", "x": "Gestor que instala librerías externas de Python.\n\npip install requests descarga e instala la librería requests desde PyPI, el repositorio oficial. pip list muestra lo instalado y pip uninstall elimina una librería. Se ejecuta en la terminal, no dentro de Python.", "u": "Añadir herramientas creadas por la comunidad.\n\nQuieres instalar la librería requests para pedir datos a internet.", "p": ["pip instala librerías externas.", "Las librerías se descargan de PyPI.", "pip se usa en la terminal, no dentro del código."], "c": "# En la terminal (no es código Python):\n#   pip install requests\n#   pip list\n#   pip uninstall requests\nprint(\"pip se ejecuta en la terminal, no en Python\")", "h": "Resume tres comandos de pip que se escriben en la terminal.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El comando que instala una librería es pip ___. (7 letras)", "e": "Escribir pip install dentro de un archivo .py."},
  {"m": "Qué es Python", "t": "Entornos virtuales", "x": "Carpetas aisladas con sus propias librerías para cada proyecto.\n\nCon python -m venv .venv creas un entorno. Al activarlo, pip instala solo dentro de él. Así un proyecto puede usar una versión de una librería y otro una distinta. Es un hábito profesional: un entorno por cada proyecto.", "u": "Evitar conflictos entre proyectos distintos.\n\nDos proyectos necesitan versiones distintas de la misma librería.", "p": ["Un entorno virtual aísla las librerías de cada proyecto.", "Se crea con python -m venv.", "Conviene tener un entorno por proyecto."], "c": "# En la terminal:\n#   python -m venv .venv\n#   .venv\\Scripts\\activate        (Windows)\n#   source .venv/bin/activate      (Mac y Linux)\n#   pip install requests\nimport sys\nprint(\"Python en uso:\", sys.prefix != sys.base_prefix)", "h": "Resume cómo crear y activar un entorno virtual.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El módulo que crea entornos virtuales se llama ___. (4 letras)", "e": "Instalar todas las librerías en el Python global."},
  {"m": "Qué es Python", "t": "Errores y tracebacks", "x": "Mensajes que indican qué falló y en qué línea.\n\nPython imprime un traceback: el recorrido hasta el error, con archivo, número de línea y tipo (NameError, TypeError, SyntaxError…). Se lee de abajo hacia arriba: la última línea es el error real. Léelo entero antes de cambiar nada.", "u": "Encontrar y corregir errores.\n\nTu programa se detiene y muestra varias líneas con un número de línea y un tipo de error.", "p": ["Un traceback indica la línea y el tipo del error.", "La última línea del traceback es el error real.", "Se debe leer el mensaje completo antes de cambiar el código."], "c": "try:\n    print(variable_inexistente)\nexcept NameError as error:\n    print(\"Tipo:\", type(error).__name__)\n    print(\"Mensaje:\", error)", "h": "Captura un NameError y muestra su tipo y su mensaje.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El error por usar una variable que no existe es un ___Error. (4 letras: Name)", "e": "Ignorar el traceback y cambiar código al azar."},
  {"m": "Qué es Python", "t": "PEP 8", "x": "Guía de estilo oficial para escribir código Python.\n\nPEP 8 recomienda nombres en minúsculas con guion bajo (nombre_completo), 4 espacios de sangría, líneas de hasta 79 caracteres y espacios alrededor de los operadores. Herramientas como flake8, black o ruff lo revisan o lo aplican por ti.", "u": "Que todo el código Python se vea parecido y sea legible.\n\nQuieres seguir la guía oficial de estilo para que tu código se vea como el de otros programadores de Python.", "p": ["PEP 8 es la guía de estilo de Python.", "Los nombres de variables usan minúsculas y guion bajo.", "Herramientas como black aplican el estilo automáticamente."], "c": "# Estilo PEP 8: minúsculas con guion bajo y espacios entre operadores\nnombre_completo = \"Ana Pérez\"\nedad_minima = 18\ntotal = edad_minima + 2\nprint(nombre_completo, total)\n# Evita: NombreCompleto=\"Ana\"; edadMinima=18", "h": "Escribe nombres y operaciones siguiendo la guía de estilo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La guía oficial de estilo de Python se llama PEP ___. (un número)", "e": "Mezclar estilos de nombres en el mismo programa."},
  {"m": "Qué es Python", "t": "Cómo practicar Python", "x": "Costumbre de escribir y probar código a diario.\n\nProgramar se aprende programando. Teclea cada ejemplo (no copies y pegues), cámbialo y rómpelo a propósito. Mini-proyectos como un adivinador de números o una lista de tareas enseñan mucho. Un poco cada día funciona mejor que mucho de golpe.", "u": "Aprender más rápido y fijar lo estudiado.\n\nQuieres aprender Python de verdad y no solo memorizarlo.", "p": ["Programar se aprende escribiendo código.", "Teclear los ejemplos ayuda más que copiarlos.", "Practicar un poco cada día es mejor que mucho de golpe."], "c": "# Reto: cambia los valores y observa el resultado\nnombre = \"Ana\"\nedad = 20\nprint(\"Me llamo\", nombre, \"y tengo\", edad, \"años\")\n# Ahora crea una variable «ciudad» y muéstrala", "h": "Une un nombre y una edad en una frase y deja un reto para ampliarla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Programar se aprende ___. (11 letras: programando)", "e": "Copiar y pegar ejemplos sin escribirlos."},
  {"m": "Datos, textos y operadores", "t": "Variables y asignación", "x": "Crear una variable dándole un valor con el signo igual.\n\nnombre = \"Ana\" crea la variable nombre y le asigna el texto. El signo = no significa «igual» como en matemáticas, sino «guarda lo de la derecha en lo de la izquierda». Puedes asignar varias a la vez: a, b = 1, 2, e incluso intercambiar valores: a, b = b, a.", "u": "Guardar y reutilizar datos en el programa.\n\nQuieres guardar la puntuación de un jugador y cambiarla durante el programa.", "p": ["El signo = guarda el valor de la derecha en la variable de la izquierda.", "Se pueden asignar varias variables a la vez.", "Una variable puede cambiar de valor cuando quieras."], "c": "puntos = 0                # crea la variable\npuntos = puntos + 10      # usa su valor y lo actualiza\nprint(puntos)             # 10\na, b = 1, 2               # asignación múltiple\na, b = b, a               # intercambia los valores\nprint(a, b)               # 2 1", "h": "Crea una variable, la actualiza e intercambia dos valores.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El signo que asigna un valor a una variable es ___. (un carácter)", "e": "Leer una variable antes de asignarle un valor. El nombre está mal escrito: la variable se llama puntos, no punto."},
  {"m": "Datos, textos y operadores", "t": "Nombres de variables", "x": "Reglas y estilo para escribir identificadores.\n\nPueden llevar letras, números y guion bajo, pero no empezar por número ni usar palabras reservadas (if, for, class…). Python distingue mayúsculas de minúsculas. El estilo es snake_case: nombre_completo, edad_minima. Elige nombres que expliquen el contenido.", "u": "Que el código se entienda con facilidad.\n\nQuieres nombrar una variable de varias palabras con el estilo habitual de Python.", "p": ["Un nombre de variable no puede empezar por un número.", "Python distingue entre mayúsculas y minúsculas.", "El estilo habitual es snake_case."], "c": "nombre_completo = \"Ana Pérez\"      # snake_case\nedad_minima = 18\nTotal = 1\ntotal = 2                         # distinta de Total\nprint(nombre_completo, edad_minima, Total, total)", "h": "Usa snake_case y muestra que mayúsculas y minúsculas son nombres distintos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El estilo nombre_completo, con guion bajo entre palabras, se llama ___ case. (5 letras: snake)", "e": "Usar nombres como x1 o dato sin significado. Un nombre de variable no puede empezar por un número."},
  {"m": "Datos, textos y operadores", "t": "Enteros", "x": "Tipo int para números sin parte decimal.\n\nLos enteros pueden ser positivos o negativos y de cualquier tamaño: Python no tiene límite práctico. Se pueden escribir con guiones bajos para leerlos mejor: 1_000_000. Las operaciones entre enteros (suma, resta, multiplicación) devuelven otro entero.", "u": "Contar, numerar y hacer cálculos exactos.\n\nQuieres guardar el número de alumnos de una clase, que nunca tiene decimales.", "p": ["Un int es un número sin parte decimal.", "Python permite enteros de cualquier tamaño.", "Se pueden escribir guiones bajos para facilitar la lectura."], "c": "alumnos = 25\nmillon = 1_000_000              # los guiones bajos solo ayudan a leer\ngrande = 2 ** 100               # sin límite práctico\nprint(alumnos, millon)\nprint(grande)\nprint(type(alumnos))", "h": "Usa enteros pequeños y gigantes y muestra su tipo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de los números enteros se llama ___. (3 letras)", "e": "Pensar que los enteros de Python tienen límite como en otros lenguajes."},
  {"m": "Datos, textos y operadores", "t": "Decimales", "x": "Tipo float para números con parte decimal.\n\nLos decimales usan punto, no coma: 3.14. Se almacenan en binario, por lo que algunos cálculos dan resultados con pequeños errores: 0.1 + 0.2 da 0.30000000000000004. Para dinero exacto existe el módulo decimal; para mostrar, usa round() o un f-string.", "u": "Guardar medidas, precios y promedios.\n\nQuieres guardar el precio 4.5 para hacer cálculos con él.", "p": ["Los decimales se escriben con punto.", "Los float pueden tener pequeños errores de precisión.", "round() redondea a los decimales indicados."], "c": "precio = 4.5\nprint(type(precio))              # float\nprint(0.1 + 0.2)                 # 0.30000000000000004 (error típico de float)\nprint(round(0.1 + 0.2, 2))       # 0.3\nprint(10 / 4)                    # la división siempre da float", "h": "Muestra el tipo float y el error típico de precisión al sumar decimales.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de los números con decimales se llama ___. (5 letras)", "e": "Comparar decimales con == esperando precisión exacta."},
  {"m": "Datos, textos y operadores", "t": "Textos str", "x": "Tipo str para guardar texto entre comillas.\n\nSe escriben con comillas simples o dobles, y con triples comillas si ocupan varias líneas. Se pueden unir con + y repetir con *. len() cuenta los caracteres. Los textos son inmutables: no se puede cambiar una letra, se crea un texto nuevo.", "u": "Trabajar con nombres, frases y mensajes.\n\nQuieres guardar el nombre «Ana» como un dato de texto.", "p": ["Un str se escribe entre comillas.", "Se pueden unir textos con +.", "Los textos son inmutables."], "c": "saludo = \"Hola\"\nnombre = 'Ana'\nprint(saludo + \", \" + nombre)       # une textos\nprint(\"ja\" * 3)                     # repite: jajaja\nprint(len(\"Python\"))                # 6 caracteres\nlargo = '''Texto\nde varias líneas'''\nprint(largo)", "h": "Une, repite y mide textos, y escribe uno de varias líneas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que cuenta los caracteres de un texto es ___(). (3 letras)", "e": "Intentar cambiar una letra de un texto ya creado."},
  {"m": "Datos, textos y operadores", "t": "Booleanos en Python", "x": "Tipo bool con solo dos valores: True y False.\n\nTrue y False se escriben con la primera letra en mayúscula. Son el resultado de comparaciones como 5 > 3. Internamente True vale 1 y False vale 0, así que se pueden sumar: sum([True, True, False]) da 2.", "u": "Tomar decisiones según una condición.\n\nQuieres guardar si un usuario está activo o no.", "p": ["Los valores booleanos son True y False.", "Se escriben con la primera letra en mayúscula.", "Las comparaciones devuelven booleanos."], "c": "es_mayor = 20 >= 18          # resultado de una comparación\nactivo = False\nprint(es_mayor, activo)\nprint(type(es_mayor))\nprint(sum([True, True, False]))   # True vale 1 y False vale 0: da 2", "h": "Obtiene booleanos de una comparación y suma varios valores lógicos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los dos valores de un booleano son True y ___. (5 letras)", "e": "Escribir true o false en minúsculas. En Python el valor se escribe True con T mayúscula."},
  {"m": "Datos, textos y operadores", "t": "None", "x": "Valor especial que representa la ausencia de un dato.\n\nNone es el único valor de su tipo (NoneType). Una función sin return devuelve None. Para comprobarlo, usa is None, no == None. Se considera falsy y es muy habitual como valor por defecto de parámetros opcionales.", "u": "Indicar «todavía no hay valor» o «sin resultado».\n\nQuieres guardar que todavía no hay ningún valor en una variable.", "p": ["None representa la ausencia de valor.", "Se comprueba con is None.", "Una función sin return devuelve None."], "c": "resultado = None\nprint(resultado)                    # None\nprint(resultado is None)            # True: la forma correcta de comprobarlo\ndef no_devuelve():\n    pass\nprint(no_devuelve())                # None", "h": "Guarda None, lo comprueba con is y muestra que una función sin return lo devuelve.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor que representa la ausencia de dato es ___. (4 letras)", "e": "Comparar con == None en lugar de is None."},
  {"m": "Datos, textos y operadores", "t": "Función type", "x": "Función que devuelve el tipo de un valor.\n\ntype(5) devuelve <class 'int'>. isinstance(valor, tipo) comprueba si un valor es de un tipo y es la forma recomendada de validar datos. Los tipos básicos son int, float, str, bool, list, tuple, set y dict.", "u": "Comprobar de qué tipo es un dato.\n\nQuieres comprobar si una variable contiene un número entero antes de operar con ella.", "p": ["type() devuelve el tipo de un valor.", "isinstance() comprueba si un valor es de cierto tipo.", "Los tipos básicos incluyen int, float, str y bool."], "c": "valor = 42\nprint(type(valor))                    # <class 'int'>\nprint(isinstance(valor, int))         # True\nprint(isinstance(valor, str))         # False\nprint(isinstance(3.5, (int, float)))  # True: admite varios tipos", "h": "Consulta el tipo de un valor y lo valida con isinstance.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que comprueba si un valor es de un tipo es ___(). (10 letras)", "e": "Comparar con type(x) == int en lugar de usar isinstance."},
  {"m": "Datos, textos y operadores", "t": "Entrada con input", "x": "Función que pide un dato al usuario por teclado.\n\ninput(\"pregunta\") muestra el mensaje, espera lo que escriba la persona y lo devuelve siempre como texto, incluso si escribe un número. Para operar hay que convertirlo con int() o float(). Aquí lo simulamos con variables para que se ejecute sin teclado.", "u": "Hacer programas interactivos.\n\nQuieres preguntar la edad al usuario y calcular con ella.", "p": ["input() pide un dato por teclado.", "input() siempre devuelve un texto.", "Para calcular hay que convertir el texto con int() o float()."], "c": "# nombre = input(\"¿Cómo te llamas? \")      # así se pide en tu computadora\nnombre = \"Ana\"                              # aquí simulamos la respuesta\n# edad = int(input(\"¿Cuántos años tienes? \"))\nedad = int(\"20\")                            # input devuelve texto: lo convertimos\nprint(f\"Hola, {nombre}. El año que viene tendrás {edad + 1}\")", "h": "Simula una entrada del usuario y convierte la edad a número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que pide un dato por teclado es ___(). (5 letras)", "e": "Sumar el resultado de input sin convertirlo a número."},
  {"m": "Datos, textos y operadores", "t": "Conversión de tipos en Python", "x": "Cambiar un dato de un tipo a otro con int, float, str y bool.\n\nint(\"42\") convierte texto en entero, float(\"3.5\") en decimal, str(42) en texto y bool(0) en booleano. int(3.9) trunca a 3 sin redondear. Si el texto no tiene formato numérico (int(\"hola\")), Python lanza un ValueError.", "u": "Operar con datos que llegan en otro formato.\n\nTienes el texto «42» y quieres sumarle 1.", "p": ["int() convierte un valor en entero.", "str() convierte un valor en texto.", "int(\"hola\") produce un ValueError."], "c": "print(int(\"42\") + 1)           # 43\nprint(float(\"3.5\") * 2)         # 7.0\nprint(str(7) + \"!\")             # 7!\nprint(int(3.9))                 # 3 (trunca, no redondea)\ntry:\n    int(\"hola\")\nexcept ValueError:\n    print(\"«hola» no es un número\")", "h": "Convierte entre tipos y captura el error de una conversión inválida.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que convierte a entero es ___(). (3 letras)", "e": "Creer que int() redondea los decimales."},
  {"m": "Datos, textos y operadores", "t": "Operadores aritméticos en Python", "x": "Símbolos para sumar, restar, multiplicar y dividir.\n\n+ suma, - resta, * multiplica, / divide (siempre devuelve float), // divide en enteros, % da el resto y ** eleva a una potencia. La multiplicación y la división se evalúan antes que la suma y la resta; los paréntesis cambian el orden.", "u": "Hacer cálculos con números.\n\nQuieres dividir 7 entre 2 y obtener el resultado entero, 3.", "p": ["El operador / siempre devuelve un decimal.", "El operador // hace la división entera.", "Los paréntesis cambian el orden de las operaciones."], "c": "print(7 + 3, 7 - 3, 7 * 3)\nprint(7 / 2)          # 3.5 (siempre float)\nprint(7 // 2)         # 3   (división entera)\nprint(7 % 2)          # 1   (resto)\nprint((2 + 3) * 4)    # 20  (los paréntesis mandan)", "h": "Muestra los operadores aritméticos, la división entera y el efecto de los paréntesis.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de la división entera es ___. (2 caracteres)", "e": "Confundir / con // y esperar un entero."},
  {"m": "Datos, textos y operadores", "t": "Resto y división entera", "x": "Operaciones % y // que trabajan con restos y cocientes.\n\nn % 2 == 0 indica que n es par. 125 // 60 da 2 horas y 125 % 60 da 5 minutos restantes. divmod(125, 60) devuelve ambos a la vez. También sirven para dar la vuelta en un ciclo (días de la semana, relojes).", "u": "Saber si un número es par, dividir en grupos o convertir unidades.\n\nQuieres convertir 125 minutos en horas y minutos restantes.", "p": ["n % 2 == 0 comprueba si n es par.", "// da el cociente y % da el resto.", "divmod devuelve el cociente y el resto a la vez."], "c": "minutos = 125\nhoras = minutos // 60          # 2\nresto = minutos % 60           # 5\nprint(f\"{horas} h y {resto} min\")\nprint(divmod(125, 60))         # (2, 5)\nprint(7 % 2 == 0, 8 % 2 == 0)  # ¿par?", "h": "Convierte minutos en horas y minutos y comprueba si un número es par.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un número n es par si n % 2 es igual a ___. (un número)", "e": "Usar / en lugar de // y obtener decimales."},
  {"m": "Datos, textos y operadores", "t": "Potencias y orden de operaciones", "x": "Operador ** y reglas de prioridad entre operadores.\n\n2 ** 3 es 2 elevado a 3 (8). Los exponentes se calculan primero, luego * / // %, y al final + y -. Con igual prioridad se evalúa de izquierda a derecha, salvo ** que va de derecha a izquierda. Ante la duda, usa paréntesis.", "u": "Calcular exponentes y evitar resultados inesperados.\n\nQuieres calcular 2 elevado a 10.", "p": ["El operador ** eleva a una potencia.", "Los exponentes se calculan antes que las multiplicaciones.", "Los paréntesis aclaran el orden de evaluación."], "c": "print(2 ** 10)             # 1024\nprint(2 + 3 * 4)           # 14 (primero la multiplicación)\nprint((2 + 3) * 4)         # 20\nprint(-3 ** 2)             # -9: la potencia va antes que el signo\nprint((-3) ** 2)           # 9", "h": "Calcula potencias y muestra cómo cambia el resultado con el orden y los paréntesis.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de potencia es ___. (2 caracteres)", "e": "Escribir -3 ** 2 esperando 9."},
  {"m": "Datos, textos y operadores", "t": "Asignación compuesta en Python", "x": "Operadores que modifican una variable usando su valor actual.\n\nx += 5 equivale a x = x + 5. También existen -=, *=, /=, //=, %= y **=. Son muy habituales en bucles y acumuladores. Python no tiene los operadores ++ ni -- de otros lenguajes: se usa x += 1.", "u": "Acortar sumas, restas y contadores.\n\nQuieres sumar 1 a un contador.", "p": ["x += 5 equivale a x = x + 5.", "Python no tiene los operadores ++ ni --.", "Los operadores compuestos son habituales en bucles."], "c": "puntos = 10\npuntos += 5       # 15\npuntos *= 2       # 30\npuntos -= 10      # 20\npuntos += 1       # 21 (Python no tiene ++)\nprint(puntos)", "h": "Modifica una variable con cuatro operadores compuestos distintos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Escribe el operador que suma y asigna a la vez (2 caracteres).", "e": "Intentar usar contador++ como en otros lenguajes. Python no tiene ++: se escribe contador += 1."},
  {"m": "Datos, textos y operadores", "t": "Operadores de comparación", "x": "Símbolos que comparan dos valores y devuelven un booleano.\n\n== igual, != distinto, > mayor, < menor, >= mayor o igual, <= menor o igual. Para comparar igualdad se usan dos signos ==; un solo = es asignación. Python permite encadenar: 1 < x < 10. Los textos se comparan por orden alfabético.", "u": "Decidir según una condición.\n\nQuieres saber si una nota está entre 5 y 10 en una sola expresión.", "p": ["== comprueba igualdad y = asigna.", "Python permite comparaciones encadenadas como 1 < x < 10.", "Todas las comparaciones devuelven True o False."], "c": "nota = 7\nprint(nota >= 5)            # True\nprint(nota == 10)           # False\nprint(nota != 7)            # False\nprint(5 <= nota <= 10)      # True: comparación encadenada\nprint(\"ana\" < \"luis\")       # True: orden alfabético", "h": "Compara números y textos, incluida una comparación encadenada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que comprueba igualdad es ___. (2 caracteres)", "e": "Usar un solo = para comparar. Para comparar se usa ==; un solo = es asignación."},
  {"m": "Datos, textos y operadores", "t": "and, or y not", "x": "Operadores lógicos que combinan condiciones.\n\nand es True solo si las dos condiciones lo son; or es True si al menos una lo es; not invierte el valor. Se escriben como palabras, no con símbolos. Evalúan de izquierda a derecha y se detienen cuando conocen el resultado (cortocircuito).", "u": "Tomar decisiones con varios criterios.\n\nQuieres comprobar que alguien es mayor de edad y además tiene entrada.", "p": ["and exige que se cumplan las dos condiciones.", "or exige que se cumpla al menos una.", "not invierte un valor booleano."], "c": "edad = 20\ntiene_entrada = True\nprint(edad >= 18 and tiene_entrada)     # True: se cumplen las dos\nprint(edad < 18 or tiene_entrada)       # True: basta con una\nprint(not tiene_entrada)                # False: invierte", "h": "Combina condiciones con and, or y not.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador lógico «y» en Python es ___. (3 letras)", "e": "Usar && o || como en otros lenguajes."},
  {"m": "Datos, textos y operadores", "t": "f-strings", "x": "Textos con f delante que insertan valores entre llaves.\n\nf\"Hola, {nombre}\" reemplaza {nombre} por su valor. Dentro de las llaves puedes poner expresiones y formato: {precio:.2f} muestra dos decimales y {n:05d} rellena con ceros. Es la forma moderna y recomendada de formatear texto.", "u": "Construir frases con variables de forma clara.\n\nQuieres construir la frase «Hola, Ana, tienes 20 años» insertando variables sin concatenar.", "p": ["Un f-string lleva una f antes de las comillas.", "Los valores se insertan entre llaves.", "{precio:.2f} muestra un número con dos decimales."], "c": "nombre = \"Ana\"\nedad = 20\nprecio = 4.5\nprint(f\"Hola, {nombre}, tienes {edad} años\")\nprint(f\"El año que viene tendrás {edad + 1}\")     # admite expresiones\nprint(f\"Precio: {precio:.2f} €\")                  # dos decimales", "h": "Inserta variables, un cálculo y un número con formato en frases.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un f-string empieza con la letra ___ antes de las comillas. (una letra)", "e": "Olvidar la f y ver las llaves tal cual."},
  {"m": "Datos, textos y operadores", "t": "Métodos de str", "x": "Funciones propias de los textos para transformarlos o buscar en ellos.\n\nupper() y lower() cambian las letras, strip() quita espacios sobrantes, replace() sustituye, split() divide en una lista, join() une una lista en un texto, startswith() y find() buscan. Todos devuelven un texto nuevo: el original no cambia.", "u": "Limpiar, buscar y cambiar textos.\n\nQuieres quitar los espacios sobrantes del principio y del final de lo que escribió el usuario.", "p": ["strip() quita los espacios de los extremos.", "split() divide un texto en una lista.", "Los métodos de str no modifican el original."], "c": "frase = \"  Aprendo Python  \"\nprint(frase.strip())                        # sin espacios en los extremos\nprint(frase.upper())                        # MAYÚSCULAS\nprint(frase.replace(\"Aprendo\", \"Disfruto\").strip())\nprint(\"a,b,c\".split(\",\"))                   # ['a', 'b', 'c']\nprint(\"-\".join([\"x\", \"y\", \"z\"]))             # x-y-z", "h": "Limpia, cambia, divide y une textos con métodos de str.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que quita espacios de los extremos es ___(). (5 letras)", "e": "Creer que upper() modifica la variable original."},
  {"m": "Datos, textos y operadores", "t": "Índices y cortes de texto", "x": "Acceso a una letra o fragmento de un texto por su posición.\n\nLas posiciones empiezan en 0: \"Python\"[0] es \"P\". Los índices negativos cuentan desde el final: [-1] es la última letra. Un corte [inicio:fin] extrae un fragmento sin incluir el fin, y [::-1] invierte el texto. Los cortes también funcionan en listas.", "u": "Extraer partes de un texto.\n\nQuieres obtener las tres primeras letras de una palabra.", "p": ["La primera posición de un texto es la 0.", "El índice -1 es la última letra.", "En un corte [a:b], la posición b no se incluye."], "c": "palabra = \"Python\"\nprint(palabra[0])         # P\nprint(palabra[-1])        # n  (la última)\nprint(palabra[0:3])       # Pyt (el 3 no se incluye)\nprint(palabra[2:])        # thon\nprint(palabra[::-1])      # nohtyP (invertida)", "h": "Extrae letras sueltas, fragmentos y la palabra invertida.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La primera posición de un texto es la ___. (un número)", "e": "Pensar que el corte [0:3] incluye la posición 3."},
  {"m": "Datos, textos y operadores", "t": "Valores truthy y falsy", "x": "Valores que se comportan como verdadero o falso en una condición.\n\nSon falsy: False, None, 0, 0.0, \"\" (texto vacío), [] (lista vacía), {} y (). Todo lo demás es truthy. Por eso if nombre: es verdadero si el texto no está vacío. bool(valor) convierte cualquier valor a booleano.", "u": "Escribir condiciones más cortas y claras.\n\nQuieres saber si una lista o un texto tiene algo, sin escribir una comparación larga.", "p": ["0, texto vacío, None y las listas vacías son falsy.", "Una lista con elementos es truthy.", "bool() convierte cualquier valor en booleano."], "c": "print(bool(0), bool(\"\"), bool([]), bool(None))        # falsy: todos False\nprint(bool(1), bool(\"a\"), bool([0]), bool({\"a\": 1}))   # truthy: todos True\nnombre = \"\"\nif not nombre:\n    print(\"No escribiste tu nombre\")", "h": "Muestra qué valores se consideran falsos y cuáles verdaderos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El número 0 se considera ___. (5 letras: falsy)", "e": "Pensar que una lista con un 0 dentro es falsy."},
  {"m": "Decisiones, bucles y funciones", "t": "if en Python", "x": "Estructura que ejecuta un bloque solo si la condición es verdadera.\n\nSe escribe if condición: seguido de un bloque con sangría. No necesita paréntesis alrededor de la condición ni llaves. Los dos puntos (:) y la sangría son obligatorios. Si la condición es False, el bloque se salta.", "u": "Tomar decisiones en el programa.\n\nQuieres mostrar un aviso solo cuando la edad sea 18 o más.", "p": ["if ejecuta un bloque solo si la condición es verdadera.", "La línea del if termina con dos puntos.", "El bloque del if debe llevar sangría."], "c": "edad = 20\nif edad >= 18:\n    print(\"Eres mayor de edad\")      # solo si la condición es True\nprint(\"Fin del programa\")           # se ejecuta siempre", "h": "Muestra un aviso solo si la edad es mayor o igual a 18.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La línea de un if termina con el símbolo ___. (dos puntos)", "e": "Olvidar los dos puntos al final del if. Falta el símbolo : al final de la línea del if."},
  {"m": "Decisiones, bucles y funciones", "t": "else", "x": "Rama que se ejecuta cuando la condición del if es falsa.\n\nelse va alineado con el if y no lleva condición, solo los dos puntos. Garantiza que siempre se ejecute exactamente una de las dos ramas. Una línea como «x = a if condicion else b» es la versión corta (expresión condicional).", "u": "Elegir entre dos caminos.\n\nQuieres mostrar «Mayor» si la edad es 18 o más y «Menor» en caso contrario.", "p": ["else se ejecuta cuando el if no se cumple.", "else no lleva condición.", "Existe una versión corta: valor_si if condicion else otro."], "c": "edad = 15\nif edad >= 18:\n    print(\"Mayor de edad\")\nelse:\n    print(\"Menor de edad\")        # se ejecuta porque 15 no es >= 18\netiqueta = \"Adulto\" if edad >= 18 else \"Menor\"   # versión corta\nprint(etiqueta)", "h": "Elige entre dos mensajes con if/else y con la versión corta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La rama que se ejecuta cuando el if es falso es ___. (4 letras)", "e": "Escribir una condición después de else."},
  {"m": "Decisiones, bucles y funciones", "t": "elif", "x": "Rama intermedia que prueba otra condición.\n\nelif es la abreviatura de «else if». Python prueba cada condición de arriba abajo y ejecuta solo la primera verdadera. El orden importa: pon primero las condiciones más específicas. El else final es opcional.", "u": "Elegir entre más de dos caminos.\n\nQuieres asignar una letra según la nota: A, B o C.", "p": ["elif añade una condición intermedia.", "Se ejecuta solo la primera rama cuya condición sea verdadera.", "El orden de las condiciones importa."], "c": "nota = 7\nif nota >= 9:\n    print(\"A\")\nelif nota >= 7:\n    print(\"B\")          # esta se ejecuta\nelse:\n    print(\"C\")", "h": "Asigna una letra según la nota probando condiciones en orden.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La rama intermedia entre if y else se escribe ___. (4 letras)", "e": "Escribir else if en lugar de elif. En Python se escribe elif, no else if."},
  {"m": "Decisiones, bucles y funciones", "t": "match", "x": "Estructura que compara un valor con varios patrones.\n\nmatch valor: con varios case patron: compara de arriba abajo (disponible desde Python 3.10). El guion bajo _ actúa como caso por defecto. Es más potente que una cadena de elif porque puede desestructurar listas y objetos.", "u": "Elegir entre muchas opciones fijas de forma clara.\n\nQuieres mostrar el nombre del día según un número del 1 al 7.", "p": ["match compara un valor con varios patrones case.", "El patrón _ equivale al caso por defecto.", "match está disponible desde Python 3.10."], "c": "dia = 3\nmatch dia:\n    case 1:\n        print(\"Lunes\")\n    case 2:\n        print(\"Martes\")\n    case 3:\n        print(\"Miércoles\")        # coincide\n    case _:\n        print(\"Otro día\")         # por defecto", "h": "Muestra el nombre de un día según su número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El patrón que equivale al caso por defecto en match es ___. (un carácter)", "e": "Usar match en versiones anteriores a Python 3.10."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucle while en Python", "x": "Bucle que repite un bloque mientras se cumpla una condición.\n\nwhile condición: comprueba la condición antes de cada vuelta. Dentro del bucle debe cambiar algo para que la condición llegue a ser falsa; si no, el bucle es infinito. Es ideal para «repite hasta que ocurra algo».", "u": "Repetir cuando no se sabe cuántas veces.\n\nQuieres dividir un número entre 2 mientras sea mayor que 1, sin saber cuántas veces.", "p": ["while repite mientras la condición sea verdadera.", "La condición se comprueba antes de cada vuelta.", "Dentro del bucle debe cambiar algo para que termine."], "c": "n = 100\npasos = 0\nwhile n > 1:            # se repite mientras n sea mayor que 1\n    n = n / 2\n    pasos += 1\nprint(\"Pasos:\", pasos)", "h": "Divide un número entre dos mientras sea mayor que uno y cuenta los pasos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle que repite mientras se cumpla una condición es ___. (5 letras)", "e": "Olvidar actualizar la variable de la condición."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucle for y range", "x": "Bucle que recorre una secuencia, como un rango de números.\n\nfor i in range(5): repite 5 veces con i valiendo 0, 1, 2, 3, 4. range(inicio, fin, paso) permite empezar donde quieras (el fin no se incluye) y saltar de dos en dos. El for de Python recorre elementos, no cuenta con condición como en otros lenguajes.", "u": "Repetir un número conocido de veces.\n\nQuieres mostrar los números del 1 al 5, repitiendo la misma instrucción.", "p": ["range(5) genera los números del 0 al 4.", "En range(a, b), el valor b no se incluye.", "El tercer argumento de range es el paso."], "c": "for i in range(1, 6):          # 1, 2, 3, 4, 5 (el 6 no se incluye)\n    print(\"Vuelta\", i)\nfor par in range(0, 10, 2):    # de 2 en 2\n    print(par)", "h": "Repite cinco vueltas numeradas y cuenta de dos en dos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que genera una secuencia de números para un for es ___(). (5 letras)", "e": "Creer que range(5) incluye el 5."},
  {"m": "Decisiones, bucles y funciones", "t": "break y continue en Python", "x": "Instrucciones que cortan un bucle o saltan una vuelta.\n\nbreak termina el bucle completamente y continue salta el resto de la vuelta actual. Los bucles de Python tienen además una cláusula else que se ejecuta solo si el bucle terminó sin usar break; es útil para búsquedas.", "u": "Salir antes de tiempo o ignorar ciertos casos.\n\nQuieres dejar de recorrer una lista en cuanto encuentres el número 7.", "p": ["break termina el bucle por completo.", "continue salta solo la vuelta actual.", "El else de un bucle se ejecuta si no hubo break."], "c": "for i in range(1, 11):\n    if i % 2 == 0:\n        continue          # salta los pares\n    if i == 7:\n        break             # sale del bucle al llegar a 7\n    print(i)              # 1, 3, 5\nelse:\n    print(\"Nunca se ejecuta aquí porque hubo break\")", "h": "Salta números pares y se detiene al llegar al 7.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que termina un bucle es ___. (5 letras)", "e": "Usar break cuando se quería continue."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucles anidados en Python", "x": "Bucles escritos dentro de otros bucles.\n\nPor cada vuelta del bucle externo, el interno realiza todas sus vueltas. Un bucle de 3 con otro interno de 4 ejecuta el interior 12 veces. Se usan para tablas de multiplicar, matrices y dibujar figuras con texto.", "u": "Recorrer tablas, cuadrículas y combinaciones.\n\nQuieres imprimir una tabla de multiplicar completa recorriendo filas y columnas.", "p": ["El bucle interno completa todas sus vueltas por cada vuelta del externo.", "Dos bucles de 3 y 4 vueltas ejecutan el interior 12 veces.", "Sirven para recorrer tablas y cuadrículas."], "c": "for fila in range(1, 4):\n    linea = \"\"\n    for col in range(1, 4):\n        linea += str(fila * col) + \" \"     # el interno se repite por cada fila\n    print(linea)", "h": "Construye una tabla de multiplicar 3 por 3 con dos bucles.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un bucle dentro de otro bucle se llama bucle ___. (8 letras)", "e": "Usar el mismo nombre de contador en los dos bucles."},
  {"m": "Decisiones, bucles y funciones", "t": "Funciones con def", "x": "Bloques de código con nombre que se ejecutan al llamarlos.\n\ndef saludar(): define la función y saludar() la ejecuta. El cuerpo va con sangría. Un nombre claro en forma de verbo (calcular_total, mostrar_menu) hace el programa más fácil de leer. Una función debe definirse antes de llamarse.", "u": "Reutilizar código y dividir un programa en partes.\n\nQuieres agrupar tres líneas de código bajo un nombre para usarlas varias veces.", "p": ["Una función se define con def.", "El cuerpo de la función lleva sangría.", "Una función debe definirse antes de llamarla."], "c": "def mostrar_bienvenida():\n    print(\"¡Bienvenida!\")\n    print(\"Aprende a tu ritmo\")\n\nmostrar_bienvenida()      # llamada 1\nmostrar_bienvenida()      # llamada 2", "h": "Define una función de bienvenida y la llama dos veces.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que define una función es ___. (3 letras)", "e": "Llamar a una función antes de definirla. El cuerpo de la función debe ir con sangría."},
  {"m": "Decisiones, bucles y funciones", "t": "Parámetros y argumentos en Python", "x": "Datos que una función recibe para trabajar con ellos.\n\nLos parámetros son los nombres entre paréntesis al definir; los argumentos son los valores al llamarla. Pueden pasarse por posición (saludar(\"Ana\", \"Lima\")) o por nombre (saludar(ciudad=\"Lima\", nombre=\"Ana\")), y entonces el orden no importa.", "u": "Hacer funciones flexibles.\n\nQuieres que una función salude a quien le indiques, no siempre a la misma persona.", "p": ["Los parámetros se escriben al definir la función.", "Los argumentos son los valores que se pasan al llamarla.", "Los argumentos por nombre permiten cambiar el orden."], "c": "def saludar(nombre, ciudad):\n    print(f\"Hola, {nombre} de {ciudad}\")\n\nsaludar(\"Ana\", \"Lima\")                    # por posición\nsaludar(ciudad=\"Bogotá\", nombre=\"Luis\")   # por nombre: el orden no importa", "h": "Saluda a distintas personas pasando argumentos por posición y por nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los nombres entre paréntesis al definir una función son los ___. (10 letras)", "e": "Pasar los argumentos en distinto orden al esperado."},
  {"m": "Decisiones, bucles y funciones", "t": "return en Python", "x": "Instrucción que devuelve un valor desde una función.\n\nreturn termina la función y entrega un valor. Una función sin return devuelve None. print solo muestra algo; return permite guardar el resultado. Puede devolver varios valores a la vez separados por comas (en realidad, una tupla).", "u": "Obtener el resultado de una función para usarlo después.\n\nQuieres que una función calcule un total y te lo entregue para guardarlo en una variable.", "p": ["return devuelve un valor y termina la función.", "Sin return, una función devuelve None.", "Puede devolver varios valores a la vez."], "c": "def sumar(a, b):\n    return a + b           # devuelve y termina\n    print(\"No se ejecuta\")\n\ntotal = sumar(3, 4)        # el resultado se guarda\nprint(total)               # 7\n\ndef min_max(lista):\n    return min(lista), max(lista)    # devuelve dos valores\nprint(min_max([4, 9, 2]))", "h": "Devuelve una suma y un par de valores desde funciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que devuelve un valor desde una función es ___. (6 letras)", "e": "Usar print en lugar de return y no poder guardar el resultado. Falta return: sin él la función devuelve None."},
  {"m": "Decisiones, bucles y funciones", "t": "Valores por defecto", "x": "Valores que usa un parámetro cuando no se le pasa argumento.\n\ndef saludar(nombre=\"visitante\") usa «visitante» si llamas a saludar() sin argumento. Los parámetros con valor por defecto van después de los obligatorios. No uses una lista o diccionario vacíos como valor por defecto: se comparten entre llamadas; usa None.", "u": "Evitar errores cuando falta un dato opcional.\n\nQuieres que una función use «visitante» si no le dicen el nombre.", "p": ["Un parámetro por defecto se escribe parámetro=valor.", "Los parámetros opcionales van después de los obligatorios.", "No conviene usar listas vacías como valor por defecto."], "c": "def saludar(nombre=\"visitante\"):\n    print(f\"Hola, {nombre}\")\n\nsaludar(\"Ana\")        # Hola, Ana\nsaludar()             # Hola, visitante", "h": "Saluda con un nombre por defecto cuando no se indica ninguno.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un parámetro por defecto se escribe parámetro ___ valor. (un carácter)", "e": "Usar una lista vacía como valor por defecto."},
  {"m": "Decisiones, bucles y funciones", "t": "Argumentos variables", "x": "Parámetros *args y **kwargs que aceptan cantidades variables de datos.\n\n*args agrupa los argumentos posicionales sobrantes en una tupla y **kwargs agrupa los argumentos por nombre en un diccionario. Con ellos una función como sumar(1, 2, 3, 4) puede recibir cualquier cantidad de números.", "u": "Crear funciones que reciben tantos valores como se quiera.\n\nQuieres una función que sume cuantos números le pases, sin saber cuántos serán.", "p": ["*args agrupa argumentos posicionales en una tupla.", "**kwargs agrupa argumentos por nombre en un diccionario.", "Permiten recibir una cantidad variable de datos."], "c": "def sumar(*numeros):\n    return sum(numeros)\n\nprint(sumar(1, 2, 3, 4))          # 10\n\ndef ficha(**datos):\n    for clave, valor in datos.items():\n        print(clave, \"=\", valor)\n\nficha(nombre=\"Ana\", edad=20)", "h": "Suma una cantidad variable de números y muestra datos recibidos por nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El parámetro que agrupa argumentos posicionales sobrantes es ___args. (un carácter: *)", "e": "Olvidar el asterisco y recibir un único valor."},
  {"m": "Decisiones, bucles y funciones", "t": "Ámbito de variables en Python", "x": "Zona del código donde una variable existe.\n\nUna variable creada dentro de una función es local y solo existe ahí. Las variables definidas fuera son globales y pueden leerse desde las funciones, pero para modificarlas hay que declarar global (se desaconseja). Es mejor pasar datos por parámetros y devolver resultados.", "u": "Saber dónde se puede leer cada variable.\n\nUna variable creada dentro de una función no se puede leer desde fuera.", "p": ["Una variable local solo existe dentro de su función.", "Una variable global se puede leer desde las funciones.", "Es mejor pasar datos por parámetros que modificar globales."], "c": "global_ = \"visible en todas partes\"\ndef prueba():\n    local = \"solo existe aquí\"\n    print(global_, local)\n\nprueba()\ntry:\n    print(local)                 # no existe fuera de la función\nexcept NameError:\n    print(\"local no existe fuera de la función\")", "h": "Compara una variable global con otra local que no existe fuera de su función.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una variable que solo existe dentro de una función es ___. (5 letras)", "e": "Intentar usar fuera de una función una variable local."},
  {"m": "Decisiones, bucles y funciones", "t": "lambda", "x": "Función anónima de una sola expresión.\n\nlambda x: x * 2 equivale a una función que devuelve el doble. Solo admite una expresión, sin return ni varias líneas. Se usa sobre todo como argumento de sorted, map o filter. Si la lógica es más larga, es mejor usar def.", "u": "Escribir funciones muy cortas donde se necesitan.\n\nNecesitas una función muy corta para indicar cómo ordenar una lista, usada solo una vez.", "p": ["lambda crea una función anónima de una sola expresión.", "No lleva return explícito.", "Se usa mucho como argumento de sorted, map y filter."], "c": "doble = lambda x: x * 2\nprint(doble(21))                        # 42\npalabras = [\"pera\", \"kiwi\", \"manzana\"]\nprint(sorted(palabras, key=lambda p: len(p)))    # ordena por longitud", "h": "Define una función lambda y la usa para ordenar palabras por longitud.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que crea una función anónima es ___. (6 letras)", "e": "Intentar escribir varias líneas dentro de una lambda."},
  {"m": "Decisiones, bucles y funciones", "t": "Recursividad en Python", "x": "Técnica en la que una función se llama a sí misma.\n\nUna función recursiva necesita un caso base (cuándo parar) y un caso recursivo (cómo acercarse al caso base). Sin caso base, Python lanza RecursionError al superar unas mil llamadas. Muchos problemas recursivos pueden resolverse también con bucles.", "u": "Resolver problemas que se repiten de forma similar.\n\nQuieres calcular el factorial de un número con una función que se llama a sí misma.", "p": ["Una función recursiva se llama a sí misma.", "Necesita un caso base para detenerse.", "Sin caso base se produce un RecursionError."], "c": "def factorial(n):\n    if n <= 1:\n        return 1                    # caso base: aquí se detiene\n    return n * factorial(n - 1)     # caso recursivo\n\nprint(factorial(5))                 # 120", "h": "Calcula un factorial con una función que se llama a sí misma.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La condición que detiene una función recursiva es el caso ___. (4 letras)", "e": "Olvidar el caso base y provocar un RecursionError."},
  {"m": "Decisiones, bucles y funciones", "t": "Docstrings", "x": "Texto entre triples comillas que documenta una función.\n\nLa primera línea de una función puede ser una cadena entre triples comillas que describe su propósito, sus parámetros y lo que devuelve. help(funcion) y los editores la muestran al usar la función. Documentar es una señal de calidad profesional.", "u": "Explicar qué hace una función y cómo se usa.\n\nQuieres dejar escrito dentro de una función qué hace, para que cualquiera pueda consultarlo.", "p": ["Un docstring se escribe con triples comillas dentro de la función.", "help() muestra el docstring de una función.", "Los docstrings explican qué hace la función."], "c": "def area_circulo(radio):\n    \"\"\"Calcula el área de un círculo.\n\n    radio: radio del círculo (número positivo).\n    Devuelve el área como número decimal.\n    \"\"\"\n    return 3.1416 * radio ** 2\n\nprint(area_circulo(2))\nprint(area_circulo.__doc__.splitlines()[0])", "h": "Documenta una función con un docstring y lo consulta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un docstring se escribe entre ___ comillas. (6 letras: triples)", "e": "Escribir un comentario con # en vez de un docstring."},
  {"m": "Decisiones, bucles y funciones", "t": "Funciones integradas", "x": "Funciones que Python ya trae listas para usar.\n\nlen cuenta elementos, sum suma, min y max encuentran el menor y mayor, abs da el valor absoluto, round redondea, sorted ordena, reversed invierte, any y all comprueban condiciones, enumerate numera y zip une listas. Conócelas: te ahorran mucho código.", "u": "Evitar escribir de nuevo operaciones comunes.\n\nQuieres saber el mayor de una lista de números sin escribir ningún bucle.", "p": ["len() cuenta los elementos de una secuencia.", "sum(), min() y max() trabajan sobre listas de números.", "sorted() devuelve una lista ordenada sin modificar la original."], "c": "numeros = [4, 9, 2, 7]\nprint(len(numeros), sum(numeros))             # 4 22\nprint(min(numeros), max(numeros))             # 2 9\nprint(sorted(numeros))                        # [2, 4, 7, 9]\nprint(abs(-5), round(3.14159, 2))             # 5 3.14\nprint(any(n > 8 for n in numeros), all(n > 1 for n in numeros))", "h": "Usa seis funciones integradas para medir, sumar, ordenar y comprobar una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que devuelve el mayor de varios valores es ___(). (3 letras)", "e": "Escribir un bucle para algo que ya hace sum() o max()."},
  {"m": "Decisiones, bucles y funciones", "t": "Bucle for sobre listas y textos", "x": "Bucle que recorre directamente los elementos de una secuencia.\n\nfor fruta in frutas: da en cada vuelta un elemento de la lista, sin contadores. También recorre los caracteres de un texto. Es más claro y menos propenso a errores que recorrer con range(len(lista)); usa el índice solo cuando de verdad lo necesites.", "u": "Procesar cada elemento sin manejar índices.\n\nQuieres mostrar cada nombre de una lista sin preocuparte por los índices.", "p": ["for recorre directamente los elementos de una lista.", "También puede recorrer los caracteres de un texto.", "No hace falta manejar índices para recorrer una lista."], "c": "frutas = [\"manzana\", \"pera\", \"uva\"]\nfor fruta in frutas:              # fruta toma cada elemento\n    print(\"Me gusta la\", fruta)\nfor letra in \"Hola\":              # también recorre textos\n    print(letra)", "h": "Recorre una lista y las letras de un texto sin usar índices.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En for fruta ___ frutas, la palabra que va antes de la lista es ___. (2 letras: in)", "e": "Recorrer con range(len(lista)) cuando bastaba recorrer la lista."},
  {"m": "Decisiones, bucles y funciones", "t": "Depurar con print", "x": "Técnica de mostrar valores intermedios para encontrar errores.\n\nCuando un cálculo da algo distinto a lo esperado, imprime los valores en los puntos clave y compáralos con lo que deberían ser. También existen el depurador (pdb o el de tu editor) y los asserts, que comprueban suposiciones: assert x > 0, \"x debe ser positivo\".", "u": "Descubrir por qué un programa no hace lo esperado.\n\nUn cálculo da un resultado distinto al esperado y quieres inspeccionar los valores intermedios.", "p": ["Mostrar valores intermedios ayuda a localizar errores.", "assert comprueba que una suposición sea cierta.", "Conviene comparar lo esperado con lo real."], "c": "def promedio(a, b, c):\n    print(\"Entradas:\", a, b, c)        # ¿llegan bien los datos?\n    suma = a + b + c\n    print(\"Suma:\", suma)               # ¿es la suma esperada?\n    return suma / 3\n\nprint(\"Resultado:\", promedio(6, 8, 10))\nassert promedio(3, 3, 3) == 3, \"el promedio de tres 3 debe ser 3\"", "h": "Imprime valores intermedios y comprueba una suposición con assert.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que comprueba que una suposición sea cierta es ___. (6 letras)", "e": "Cambiar código al azar sin inspeccionar los valores."},
  {"m": "Listas, diccionarios y colecciones", "t": "Listas", "x": "Colección ordenada y modificable de elementos entre corchetes.\n\nSe escriben entre corchetes y separados por comas: [\"Ana\", \"Luis\"]. Pueden contener cualquier tipo, incluso mezclados. Cada elemento tiene una posición que empieza en 0. len() dice cuántos hay y se pueden modificar elementos individualmente.", "u": "Manejar muchos datos relacionados en una variable.\n\nQuieres guardar cinco nombres de alumnos en una sola variable que se pueda modificar.", "p": ["Una lista se escribe entre corchetes.", "Los elementos de una lista se pueden modificar.", "La primera posición de una lista es la 0."], "c": "alumnos = [\"Ana\", \"Luis\", \"Marta\"]\nprint(alumnos[0])              # Ana (primera posición = 0)\nprint(len(alumnos))            # 3\nalumnos[1] = \"Pablo\"           # se puede modificar\nprint(alumnos)", "h": "Lee, mide y modifica elementos de una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una lista se escribe entre ___. (corchetes)", "e": "Pedir el elemento en la posición len(lista) y salirse del rango. La lista solo tiene las posiciones 0 y 1: la 2 está fuera de rango (IndexError)."},
  {"m": "Listas, diccionarios y colecciones", "t": "Cortes de listas", "x": "Forma de extraer una parte de una lista con [inicio:fin].\n\nlista[1:3] devuelve los elementos de la posición 1 a la 2 (el fin no se incluye). lista[:2] son los dos primeros, lista[-2:] los dos últimos y lista[::2] uno de cada dos. Un corte siempre devuelve una lista nueva y no modifica la original.", "u": "Obtener sublistas y copias rápidas.\n\nQuieres obtener los tres primeros elementos de una lista sin modificarla.", "p": ["En [a:b], la posición b no se incluye.", "[-2:] devuelve los dos últimos elementos.", "Un corte devuelve una lista nueva."], "c": "letras = [\"a\", \"b\", \"c\", \"d\", \"e\"]\nprint(letras[1:3])       # ['b', 'c']\nprint(letras[:3])        # ['a', 'b', 'c']\nprint(letras[-2:])       # ['d', 'e']\nprint(letras[::2])       # ['a', 'c', 'e']\nprint(letras)            # la original no cambia", "h": "Extrae varios fragmentos de una lista sin modificarla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En lista[1:3], la posición ___ no se incluye. (un número)", "e": "Pensar que el índice final del corte se incluye."},
  {"m": "Listas, diccionarios y colecciones", "t": "Añadir y quitar elementos de una lista", "x": "Métodos append, insert, remove y pop para modificar una lista.\n\nappend añade al final, insert añade en una posición, remove quita el primer elemento con ese valor y pop quita (y devuelve) el de una posición, por defecto el último. extend une otra lista y del borra por posición. Todos modifican la lista original.", "u": "Hacer crecer o encoger una lista durante el programa.\n\nQuieres añadir un nombre al final de una lista ya creada.", "p": ["append añade un elemento al final.", "pop quita y devuelve un elemento.", "remove quita el primer elemento con ese valor."], "c": "cola = [\"Ana\", \"Luis\"]\ncola.append(\"Marta\")          # final\ncola.insert(0, \"Pablo\")       # en la posición 0\nprint(cola)\nsalio = cola.pop(0)           # quita y devuelve el primero\ncola.remove(\"Luis\")           # quita por valor\nprint(salio, cola)", "h": "Añade y quita elementos de una lista de varias formas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que añade un elemento al final es ___(). (6 letras)", "e": "Usar remove con un valor que no está en la lista."},
  {"m": "Listas, diccionarios y colecciones", "t": "Recorrer y comprobar listas", "x": "Formas de recorrer una lista y comprobar si contiene algo.\n\nfor x in lista recorre; x in lista devuelve True o False; lista.index(x) da la posición (error si no está) y lista.count(x) cuenta cuántas veces aparece. Comprobar con in antes de usar index evita errores.", "u": "Buscar, contar y procesar elementos.\n\nQuieres saber si «Ana» está en una lista de invitados.", "p": ["El operador in comprueba si un valor está en la lista.", "count() cuenta cuántas veces aparece un valor.", "index() da la posición de un valor."], "c": "invitados = [\"Ana\", \"Luis\", \"Marta\", \"Ana\"]\nprint(\"Ana\" in invitados)            # True\nprint(\"Pablo\" not in invitados)      # True\nprint(invitados.index(\"Marta\"))      # 2\nprint(invitados.count(\"Ana\"))        # 2", "h": "Comprueba presencia, posición y cantidad de un valor en una lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que comprueba si un valor está en una lista es ___. (2 letras)", "e": "Usar index sin comprobar antes que el valor existe."},
  {"m": "Listas, diccionarios y colecciones", "t": "Ordenar listas", "x": "Métodos sort y sorted para ordenar elementos.\n\nlista.sort() ordena la lista original y devuelve None. sorted(lista) devuelve una lista nueva ordenada sin tocar la original. reverse=True ordena de mayor a menor y key=función indica el criterio (por ejemplo len o una lambda).", "u": "Mostrar listas de menor a mayor o por otro criterio.\n\nQuieres obtener una copia ordenada de una lista, sin cambiar la original.", "p": ["sort() modifica la lista original.", "sorted() devuelve una lista nueva.", "reverse=True ordena de mayor a menor."], "c": "numeros = [10, 9, 1, 100]\nprint(sorted(numeros))                    # [1, 9, 10, 100]\nprint(sorted(numeros, reverse=True))      # de mayor a menor\nprint(numeros)                            # la original no cambia\npalabras = [\"pera\", \"kiwi\", \"manzana\"]\npalabras.sort(key=len)                    # ordena la propia lista por longitud\nprint(palabras)", "h": "Ordena una lista de varias formas, con y sin modificar la original.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que devuelve una lista ordenada nueva es ___(). (6 letras)", "e": "Escribir lista = lista.sort() y quedarse con None. sort() devuelve None: así la variable numeros pierde la lista."},
  {"m": "Listas, diccionarios y colecciones", "t": "Copiar listas", "x": "Diferencia entre copiar una lista y copiar la referencia.\n\nb = a no copia la lista: ambas variables apuntan a la misma. Para copiar usa a.copy(), a[:] o list(a). Es una copia superficial: si la lista contiene otras listas, estas se comparten. copy.deepcopy copia todo el contenido en profundidad.", "u": "Evitar cambios inesperados al copiar.\n\nAl cambiar una copia de una lista cambia también la original.", "p": ["b = a no crea una copia independiente de una lista.", "copy() y [:] crean una copia superficial.", "deepcopy copia también los objetos internos."], "c": "a = [1, 2, 3]\nb = a                  # NO es una copia: apunta a la misma lista\nb.append(4)\nprint(a)               # [1, 2, 3, 4]\nc = a.copy()           # copia real\nc.append(5)\nprint(a, c)", "h": "Muestra que asignar no copia y que copy() sí crea una copia independiente.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que crea una copia de una lista es ___(). (4 letras)", "e": "Creer que b = a copia la lista."},
  {"m": "Listas, diccionarios y colecciones", "t": "Listas anidadas", "x": "Listas que contienen otras listas como elementos.\n\n[[1, 2], [3, 4]] es una lista de dos filas. Se accede con dos índices: tabla[1][0] es 3. Se recorren con bucles anidados. Son ideales para tableros de juegos, hojas de datos y matrices matemáticas.", "u": "Representar tablas, cuadrículas o matrices.\n\nQuieres representar un tablero de 3 filas por 3 columnas.", "p": ["Una lista anidada contiene otras listas.", "Se accede con dos índices: lista[fila][columna].", "Se recorren con bucles anidados."], "c": "tablero = [\n    [\"X\", \"O\", \"X\"],\n    [\"O\", \"X\", \"O\"],\n    [\"O\", \"O\", \"X\"],\n]\nprint(tablero[0][2])          # X: fila 0, columna 2\ntablero[1][1] = \"-\"\nfor fila in tablero:\n    print(\" \".join(fila))", "h": "Crea un tablero como lista de listas y lo muestra fila por fila.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una lista dentro de otra lista se llama lista ___. (8 letras)", "e": "Intercambiar fila y columna al acceder."},
  {"m": "Listas, diccionarios y colecciones", "t": "Tuplas", "x": "Secuencia ordenada e inmutable entre paréntesis.\n\nUna tupla se escribe (3, 4) y no se puede modificar después de creada. Son más ligeras que las listas y pueden usarse como claves de diccionario. Una tupla de un solo elemento lleva coma: (5,). Las funciones que devuelven varios valores devuelven una tupla.", "u": "Guardar datos que no deben cambiar, como coordenadas.\n\nQuieres guardar unas coordenadas (x, y) que nunca deben cambiar.", "p": ["Una tupla se escribe entre paréntesis.", "Una tupla no se puede modificar.", "Una tupla de un elemento necesita una coma."], "c": "punto = (3, 4)\nprint(punto[0], len(punto))        # 3 2\ntry:\n    punto[0] = 10                  # no se puede modificar\nexcept TypeError:\n    print(\"Las tuplas no se modifican\")\nuno = (5,)                         # con una sola coma\nprint(type(uno), type((5)))", "h": "Crea una tupla, intenta modificarla y muestra la coma de un solo elemento.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una secuencia que no se puede modificar es una ___. (5 letras)", "e": "Olvidar la coma en una tupla de un solo elemento."},
  {"m": "Listas, diccionarios y colecciones", "t": "Desempaquetado", "x": "Asignar los elementos de una secuencia a varias variables.\n\nx, y = (3, 4) crea x = 3 e y = 4. El número de variables debe coincidir, salvo que uses * para recoger el resto: primero, *resto = [1, 2, 3, 4]. Se usa al recorrer pares y al recibir varios valores de una función.", "u": "Sacar valores de listas y tuplas en una línea.\n\nUna función devuelve (3, 4) y quieres guardar cada valor en su variable en una sola línea.", "p": ["El desempaquetado asigna cada elemento a una variable.", "El número de variables debe coincidir con los elementos.", "Con * se recogen los elementos sobrantes."], "c": "x, y = (3, 4)\nprint(x, y)\nprimero, *resto = [10, 20, 30, 40]\nprint(primero, resto)               # 10 [20, 30, 40]\ndef min_max(lista):\n    return min(lista), max(lista)\nmenor, mayor = min_max([4, 9, 2])\nprint(menor, mayor)", "h": "Reparte valores de secuencias en variables, incluyendo los sobrantes con *.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El símbolo que recoge los elementos sobrantes es ___. (un carácter)", "e": "Usar más variables que elementos y provocar un ValueError."},
  {"m": "Listas, diccionarios y colecciones", "t": "Conjuntos set", "x": "Colección sin orden ni elementos repetidos.\n\nSe escribe con llaves {1, 2, 3} o set(lista). No admite elementos repetidos ni tiene posiciones. Es muy rápido para comprobar si un valor está dentro. set(lista) es la forma clásica de quitar duplicados. Un conjunto vacío se crea con set(), no con {}.", "u": "Eliminar duplicados y comprobar pertenencia rápido.\n\nQuieres quitar los valores repetidos de una lista.", "p": ["Un set no admite elementos repetidos.", "Un set no tiene orden ni posiciones.", "Un conjunto vacío se crea con set()."], "c": "repetidos = [1, 2, 2, 3, 3, 3]\nunicos = set(repetidos)\nprint(unicos)                        # {1, 2, 3}\nunicos.add(4)\nprint(4 in unicos, len(unicos))      # True 4\nprint(type({}), type(set()))         # {} es un diccionario, no un conjunto", "h": "Elimina duplicados con un set y muestra por qué {} no crea un conjunto vacío.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La estructura que no admite elementos repetidos es el ___. (3 letras)", "e": "Crear un set vacío con {} y obtener un diccionario."},
  {"m": "Listas, diccionarios y colecciones", "t": "Operaciones con conjuntos", "x": "Unión, intersección y diferencia entre conjuntos.\n\na | b es la unión (todo), a & b la intersección (lo común), a - b la diferencia (lo que está en a pero no en b) y a ^ b lo que está en uno solo. Son perfectas para comparar listas de alumnos, etiquetas o permisos.", "u": "Comparar colecciones: qué comparten y qué las distingue.\n\nQuieres saber qué alumnos están en las dos clases a la vez.", "p": ["a & b devuelve los elementos comunes.", "a | b devuelve la unión de los dos conjuntos.", "a - b devuelve lo que está en a y no en b."], "c": "clase_a = {\"Ana\", \"Luis\", \"Marta\"}\nclase_b = {\"Luis\", \"Pablo\", \"Marta\"}\nprint(clase_a & clase_b)       # en las dos: Luis, Marta\nprint(clase_a | clase_b)       # todos\nprint(clase_a - clase_b)       # solo en A: Ana\nprint(clase_a ^ clase_b)       # en una sola clase", "h": "Compara dos conjuntos de alumnos con las cuatro operaciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de intersección de conjuntos es ___. (un carácter)", "e": "Confundir la intersección con la unión."},
  {"m": "Listas, diccionarios y colecciones", "t": "Diccionarios", "x": "Colección de pares clave-valor entre llaves.\n\n{\"nombre\": \"Ana\", \"edad\": 20} asocia cada clave con un valor. Se accede con la clave: persona[\"nombre\"]. Las claves deben ser únicas e inmutables (textos, números, tuplas). Desde Python 3.7 conservan el orden de inserción.", "u": "Asociar datos con nombres para encontrarlos rápido.\n\nQuieres guardar nombre, edad y ciudad de una persona en una sola variable.", "p": ["Un diccionario guarda pares clave-valor entre llaves.", "Se accede a un valor con su clave entre corchetes.", "Las claves de un diccionario son únicas."], "c": "persona = {\"nombre\": \"Ana\", \"edad\": 20, \"ciudad\": \"Lima\"}\nprint(persona[\"nombre\"])               # Ana\npersona[\"edad\"] = 21                   # modificar\npersona[\"correo\"] = \"ana@correo.com\"   # añadir\ndel persona[\"ciudad\"]                  # borrar\nprint(persona, len(persona))", "h": "Crea un diccionario y lee, modifica, añade y borra datos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un diccionario se escribe entre ___. (llaves)", "e": "Leer una clave que no existe y provocar un KeyError. La clave edad no existe: Python lanza un KeyError."},
  {"m": "Listas, diccionarios y colecciones", "t": "Métodos de diccionarios", "x": "Get, keys, values, items, pop y update para trabajar con diccionarios.\n\nget(clave, defecto) lee sin error si no existe. keys(), values() e items() devuelven las claves, los valores y los pares. pop(clave) quita y devuelve; update(otro) fusiona dos diccionarios. setdefault añade una clave solo si falta.", "u": "Leer, recorrer y modificar diccionarios con seguridad.\n\nQuieres leer una clave que puede no existir y obtener un valor por defecto en vez de un error.", "p": ["get() lee un valor sin provocar error si falta la clave.", "items() devuelve los pares clave-valor.", "update() fusiona otro diccionario."], "c": "persona = {\"nombre\": \"Ana\", \"edad\": 20}\nprint(persona.get(\"ciudad\", \"sin ciudad\"))     # no falla\nprint(list(persona.keys()))                    # ['nombre', 'edad']\nprint(list(persona.values()))                  # ['Ana', 20]\npersona.update({\"edad\": 21, \"pais\": \"Perú\"})   # fusiona\nprint(persona)\nprint(persona.pop(\"pais\"), persona)", "h": "Lee con valor por defecto, lista claves y valores, fusiona y quita datos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que lee una clave sin provocar error es ___(). (3 letras)", "e": "Leer con corchetes una clave que puede no existir."},
  {"m": "Listas, diccionarios y colecciones", "t": "Recorrer diccionarios", "x": "Formas de recorrer claves, valores o pares de un diccionario.\n\nfor clave in dic recorre las claves. for valor in dic.values() recorre los valores y for clave, valor in dic.items() los pares. Es la forma más habitual. No se debe añadir ni borrar claves mientras se recorre el diccionario.", "u": "Procesar todos los datos de un diccionario.\n\nQuieres mostrar cada producto con su precio.", "p": ["for x in diccionario recorre las claves.", "items() permite recorrer clave y valor a la vez.", "No se deben añadir ni quitar claves mientras se recorre."], "c": "precios = {\"pan\": 1.2, \"leche\": 0.9, \"huevos\": 2.5}\nfor producto in precios:                        # solo claves\n    print(producto)\nfor producto, precio in precios.items():        # pares\n    print(f\"{producto}: {precio} €\")\nprint(sum(precios.values()))                    # suma de valores", "h": "Recorre un diccionario por claves y por pares y suma sus valores.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método para recorrer claves y valores a la vez es ___(). (5 letras)", "e": "Modificar el diccionario mientras se recorre."},
  {"m": "Listas, diccionarios y colecciones", "t": "Diccionarios anidados", "x": "Diccionarios cuyos valores son otros diccionarios o listas.\n\nUn alumno puede ser un diccionario con una lista de notas: {\"nombre\": \"Ana\", \"notas\": [8, 9]}. Se accede encadenando claves: alumnos[\"ana\"][\"notas\"][0]. Es la misma estructura que usa JSON en las API.", "u": "Representar datos con estructura, como fichas de alumnos.\n\nQuieres guardar varios alumnos, cada uno con su lista de notas.", "p": ["Un diccionario puede contener otros diccionarios y listas.", "Se accede encadenando claves e índices.", "Es la estructura que usa JSON."], "c": "alumnos = {\n    \"ana\":  {\"edad\": 20, \"notas\": [8, 9, 7]},\n    \"luis\": {\"edad\": 22, \"notas\": [6, 5]},\n}\nprint(alumnos[\"ana\"][\"edad\"])               # 20\nprint(alumnos[\"luis\"][\"notas\"][0])          # 6\nalumnos[\"ana\"][\"notas\"].append(10)\nfor nombre, ficha in alumnos.items():\n    print(nombre, sum(ficha[\"notas\"]) / len(ficha[\"notas\"]))", "h": "Guarda alumnos con sus notas y calcula el promedio de cada uno.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En alumnos[\"ana\"][\"edad\"], «ana» es una ___. (5 letras)", "e": "Olvidar una de las claves intermedias al acceder."},
  {"m": "Listas, diccionarios y colecciones", "t": "Comprensión de listas", "x": "Forma corta de crear una lista a partir de otra.\n\n[x * 2 for x in numeros] crea una lista con el doble de cada número. Se puede filtrar con if: [x for x in numeros if x > 5]. Es más rápida y legible que un bucle con append, siempre que no se complique demasiado.", "u": "Transformar y filtrar listas en una sola línea.\n\nQuieres crear una lista con el doble de cada número de otra, en una sola línea.", "p": ["Una comprensión de lista crea una lista en una línea.", "Puede incluir un if para filtrar.", "Es más corta que un bucle con append."], "c": "numeros = [1, 2, 3, 4, 5, 6]\ndobles = [n * 2 for n in numeros]\npares = [n for n in numeros if n % 2 == 0]\ncuadrados_pares = [n ** 2 for n in numeros if n % 2 == 0]\nprint(dobles)\nprint(pares)\nprint(cuadrados_pares)", "h": "Crea listas transformando y filtrando otra lista en una sola línea.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En [n * 2 for n in lista], la palabra que introduce el bucle es ___. (3 letras)", "e": "Escribir comprensiones tan largas que no se entienden."},
  {"m": "Listas, diccionarios y colecciones", "t": "Comprensión de diccionarios y conjuntos", "x": "Comprensiones que crean diccionarios o conjuntos en una línea.\n\n{p: len(p) for p in palabras} crea un diccionario palabra → longitud. {x % 3 for x in numeros} crea un conjunto. Funcionan igual que las de lista, con llaves y, en el caso del diccionario, con el par clave: valor.", "u": "Construir estructuras a partir de otras con pocas líneas.\n\nQuieres crear un diccionario que asocie cada palabra con su longitud en una sola línea.", "p": ["Una comprensión de diccionario usa llaves y clave: valor.", "Una comprensión de conjunto usa llaves sin pares.", "Siguen la misma lógica que las de lista."], "c": "palabras = [\"pera\", \"kiwi\", \"manzana\"]\nlongitudes = {p: len(p) for p in palabras}\nprint(longitudes)                   # {'pera': 4, 'kiwi': 4, 'manzana': 7}\nrestos = {n % 3 for n in range(10)}\nprint(restos)                       # {0, 1, 2}", "h": "Crea un diccionario de longitudes y un conjunto de restos con comprensiones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En una comprensión de diccionario, clave y valor se separan con ___. (dos puntos)", "e": "Olvidar los dos puntos entre clave y valor."},
  {"m": "Listas, diccionarios y colecciones", "t": "enumerate y zip", "x": "Funciones que numeran elementos o recorren varias listas a la vez.\n\nenumerate(lista) da pares (posición, elemento); admite start=1 para contar desde uno. zip(a, b) empareja elementos de dos listas y se detiene en la más corta. Se combinan con desempaquetado en el for.", "u": "Recorrer con índices o emparejar listas sin bucles complicados.\n\nQuieres recorrer una lista mostrando el número de cada elemento.", "p": ["enumerate entrega la posición y el elemento.", "zip empareja elementos de varias listas.", "zip se detiene cuando termina la lista más corta."], "c": "frutas = [\"manzana\", \"pera\", \"uva\"]\nfor i, fruta in enumerate(frutas, start=1):\n    print(i, fruta)\nnombres = [\"Ana\", \"Luis\"]\nnotas = [9, 7]\nfor nombre, nota in zip(nombres, notas):\n    print(nombre, \"->\", nota)\nprint(dict(zip(nombres, notas)))", "h": "Numera elementos, empareja dos listas y crea un diccionario con zip.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que entrega posición y elemento es ___(). (9 letras)", "e": "Usar range(len(lista)) cuando bastaba enumerate."},
  {"m": "Listas, diccionarios y colecciones", "t": "Ordenar con key", "x": "Parámetro que indica el criterio de ordenación.\n\nsorted(lista, key=funcion) ordena según el valor que devuelve la función para cada elemento. Con listas de diccionarios se usa una lambda: key=lambda a: a[\"nota\"]. Combinado con reverse=True da rankings. Es la base de «los 3 mejores».", "u": "Ordenar listas de objetos o textos por un campo concreto.\n\nQuieres ordenar una lista de alumnos por su nota, de mayor a menor.", "p": ["El parámetro key define el criterio de ordenación.", "Con una lambda se ordena por un campo de un diccionario.", "reverse=True invierte el orden."], "c": "alumnos = [\n    {\"nombre\": \"Ana\", \"nota\": 9},\n    {\"nombre\": \"Luis\", \"nota\": 5},\n    {\"nombre\": \"Marta\", \"nota\": 8},\n]\nranking = sorted(alumnos, key=lambda a: a[\"nota\"], reverse=True)\nprint([a[\"nombre\"] for a in ranking])        # ['Ana', 'Marta', 'Luis']\nprint(ranking[0][\"nombre\"])                  # el mejor", "h": "Ordena alumnos por nota de mayor a menor y obtiene al mejor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El parámetro que indica el criterio de ordenación es ___. (3 letras)", "e": "Olvidar la lambda y ordenar por el diccionario completo."},
  {"m": "Listas, diccionarios y colecciones", "t": "Contar y agrupar", "x": "Técnicas para contar elementos y agruparlos con diccionarios.\n\nUn diccionario sirve de contador: conteo[palabra] = conteo.get(palabra, 0) + 1. El módulo collections ofrece Counter, que lo hace solo, y defaultdict, que crea valores por defecto. Con Counter(lista).most_common(3) obtienes los más frecuentes.", "u": "Calcular frecuencias y clasificaciones.\n\nQuieres contar cuántas veces aparece cada palabra en una lista.", "p": ["Un diccionario puede usarse como contador.", "Counter cuenta automáticamente los elementos.", "most_common devuelve los más frecuentes."], "c": "from collections import Counter\npalabras = [\"sol\", \"luna\", \"sol\", \"mar\", \"sol\", \"luna\"]\nconteo = {}\nfor p in palabras:\n    conteo[p] = conteo.get(p, 0) + 1          # contador manual\nprint(conteo)\nprint(Counter(palabras).most_common(2))       # los 2 más frecuentes", "h": "Cuenta palabras a mano y con Counter.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La clase de collections que cuenta elementos es ___. (7 letras)", "e": "Contar elementos con un bucle anidado cuando Counter lo resuelve."},
  {"m": "Errores, archivos y objetos", "t": "try y except", "x": "Estructura que captura errores para que el programa siga funcionando.\n\nEl código que puede fallar va en try. Si ocurre un error, Python salta al bloque except, donde puedes avisar y recuperarte. Es preferible capturar errores concretos (except ValueError) en vez de todos, para no esconder fallos que no esperabas.", "u": "Evitar que un error detenga todo el programa.\n\nQuieres que el programa siga funcionando aunque el usuario escriba un texto donde se esperaba un número.", "p": ["try contiene el código que puede fallar.", "except se ejecuta cuando ocurre el error indicado.", "Conviene capturar errores concretos."], "c": "texto = \"abc\"\ntry:\n    numero = int(texto)              # puede fallar\n    print(\"Número:\", numero)\nexcept ValueError:\n    print(\"«\" + texto + \"» no es un número válido\")\nprint(\"El programa continúa\")", "h": "Captura el error de convertir un texto que no es un número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bloque que captura un error se escribe ___. (6 letras)", "e": "Usar un except vacío que esconde todos los errores. Entre try y except no puede haber otras instrucciones: el except debe ir justo después del bloque try."},
  {"m": "Errores, archivos y objetos", "t": "else y finally", "x": "Bloques extra de try que se ejecutan sin error o siempre.\n\nelse se ejecuta solo si no hubo error en el try. finally se ejecuta siempre, haya error o no, y es ideal para cerrar archivos o conexiones. Se pueden encadenar varios except para tipos de error distintos.", "u": "Separar el éxito de la limpieza final.\n\nQuieres ejecutar una limpieza final tanto si hubo error como si no.", "p": ["else se ejecuta solo si no ocurrió ningún error.", "finally se ejecuta siempre.", "Se pueden encadenar varios except."], "c": "def dividir(a, b):\n    try:\n        r = a / b\n    except ZeroDivisionError:\n        print(\"No se puede dividir entre cero\")\n    except TypeError:\n        print(\"Solo números\")\n    else:\n        print(\"Resultado:\", r)             # solo si no hubo error\n    finally:\n        print(\"Operación terminada\")      # siempre\n\ndividir(10, 2)\ndividir(10, 0)", "h": "Divide números, captura dos tipos de error y muestra un mensaje final siempre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bloque que se ejecuta siempre es ___. (7 letras)", "e": "Poner código que puede fallar dentro de else."},
  {"m": "Errores, archivos y objetos", "t": "Lanzar errores con raise", "x": "Instrucción que provoca un error a propósito.\n\nraise ValueError(\"mensaje\") detiene la función y avisa de que algo es incorrecto. Es mejor fallar pronto con un mensaje claro que seguir con datos erróneos. Quien llama a la función puede capturar el error con try/except.", "u": "Avisar de datos inválidos y proteger funciones.\n\nQuieres que una función avise con un error si recibe una edad negativa.", "p": ["raise provoca un error de forma voluntaria.", "Conviene fallar pronto con un mensaje claro.", "Quien llama puede capturar el error con try/except."], "c": "def comprobar_edad(edad):\n    if edad < 0:\n        raise ValueError(\"La edad no puede ser negativa\")\n    return edad\n\ntry:\n    comprobar_edad(-5)\nexcept ValueError as error:\n    print(\"Error:\", error)", "h": "Lanza un error por una edad negativa y lo captura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que provoca un error voluntariamente es ___. (5 letras)", "e": "Devolver un valor falso en vez de avisar del error."},
  {"m": "Errores, archivos y objetos", "t": "Excepciones propias", "x": "Clases de error creadas por ti para casos específicos.\n\nSe crean heredando de Exception: class SaldoInsuficiente(Exception): pass. Después se lanzan con raise y se capturan por su nombre. Dan significado al error y permiten reaccionar de forma distinta según el caso.", "u": "Distinguir los errores de tu programa de los demás.\n\nQuieres un error propio llamado SaldoInsuficiente para un cajero.", "p": ["Una excepción propia hereda de Exception.", "Se lanza con raise y se captura por su nombre.", "Dan significado a los errores de tu programa."], "c": "class SaldoInsuficiente(Exception):\n    pass\n\ndef retirar(saldo, cantidad):\n    if cantidad > saldo:\n        raise SaldoInsuficiente(f\"Faltan {cantidad - saldo} €\")\n    return saldo - cantidad\n\ntry:\n    retirar(50, 80)\nexcept SaldoInsuficiente as e:\n    print(\"No se puede:\", e)", "h": "Define un error propio y lo lanza cuando el saldo no alcanza.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una excepción propia hereda de la clase ___. (9 letras)", "e": "Heredar de una clase equivocada en vez de Exception."},
  {"m": "Errores, archivos y objetos", "t": "Leer archivos", "x": "Abrir un archivo de texto y obtener su contenido.\n\nopen(\"nombre.txt\", \"r\", encoding=\"utf-8\") abre un archivo para leer. read() devuelve todo el texto, readline() una línea y readlines() una lista de líneas. También se puede recorrer con for. Si el archivo no existe, aparece un FileNotFoundError.", "u": "Usar datos guardados fuera del programa.\n\nQuieres leer el contenido de un archivo de texto desde Python.", "p": ["open() abre un archivo.", "read() devuelve todo el contenido como texto.", "Un archivo que no existe provoca FileNotFoundError."], "c": "# Preparamos un archivo de ejemplo\nwith open(\"ejemplo.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Línea uno\\nLínea dos\\nLínea tres\\n\")\n\nwith open(\"ejemplo.txt\", \"r\", encoding=\"utf-8\") as f:\n    for numero, linea in enumerate(f, start=1):\n        print(numero, linea.strip())\n\ntry:\n    open(\"no_existe.txt\")\nexcept FileNotFoundError:\n    print(\"El archivo no existe\")", "h": "Crea un archivo, lo lee línea a línea y captura el error de uno inexistente.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que abre un archivo es ___(). (4 letras)", "e": "Olvidar indicar la codificación utf-8."},
  {"m": "Errores, archivos y objetos", "t": "Escribir archivos", "x": "Guardar texto en un archivo desde Python.\n\nopen(nombre, \"w\") crea el archivo o lo vacía si ya existe; \"a\" añade al final sin borrar. write() escribe el texto exacto, sin salto de línea automático. Cuidado con \"w\": borra lo que hubiera.", "u": "Conservar resultados y registros.\n\nQuieres añadir una línea al final de un registro sin borrar lo anterior.", "p": ["El modo \"w\" crea o vacía el archivo.", "El modo \"a\" añade al final.", "write() no añade saltos de línea."], "c": "with open(\"registro.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Inicio\\n\")                    # w: crea o vacía\nwith open(\"registro.txt\", \"a\", encoding=\"utf-8\") as f:\n    f.write(\"Segunda línea\\n\")             # a: añade al final\nprint(open(\"registro.txt\", encoding=\"utf-8\").read())", "h": "Crea un archivo y le añade una línea sin borrar el contenido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El modo que añade al final de un archivo es ___. (una letra)", "e": "Usar el modo w y borrar el contenido anterior."},
  {"m": "Errores, archivos y objetos", "t": "with", "x": "Estructura que abre un recurso y lo cierra automáticamente.\n\nwith open(...) as archivo: abre el archivo y garantiza que se cierre al salir del bloque, incluso si ocurre una excepción. Es la forma recomendada de trabajar con archivos, conexiones y bloqueos.", "u": "No olvidar cerrar archivos aunque haya errores.\n\nQuieres asegurarte de que un archivo se cierre aunque ocurra un error mientras lo lees.", "p": ["with cierra el archivo automáticamente.", "El cierre ocurre aunque haya un error.", "Es la forma recomendada de abrir archivos."], "c": "with open(\"datos.txt\", \"w\", encoding=\"utf-8\") as archivo:\n    archivo.write(\"hola\")\nprint(\"¿Cerrado fuera del with?\", archivo.closed)     # True", "h": "Escribe en un archivo y comprueba que se cerró solo al salir del bloque.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que cierra un archivo automáticamente es ___. (4 letras)", "e": "Abrir archivos sin with y olvidar cerrarlos."},
  {"m": "Errores, archivos y objetos", "t": "Rutas con pathlib", "x": "Módulo que representa rutas de archivos como objetos.\n\nPath(\"datos\") / \"notas.txt\" une rutas con / sin preocuparte por la barra del sistema. Path tiene métodos como exists(), read_text(), write_text(), mkdir() y iterdir(). Funciona igual en Windows, Mac y Linux.", "u": "Trabajar con carpetas y archivos en cualquier sistema operativo.\n\nQuieres construir la ruta datos/notas.txt de forma válida en cualquier sistema operativo.", "p": ["Path representa una ruta como objeto.", "El operador / une partes de una ruta.", "Funciona igual en todos los sistemas operativos."], "c": "from pathlib import Path\ncarpeta = Path(\"datos\")\ncarpeta.mkdir(exist_ok=True)\narchivo = carpeta / \"notas.txt\"                 # une con /\narchivo.write_text(\"Mis notas\", encoding=\"utf-8\")\nprint(archivo.exists(), archivo.name, archivo.suffix)\nprint(archivo.read_text(encoding=\"utf-8\"))", "h": "Crea una carpeta, escribe y lee un archivo con pathlib.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El módulo que representa rutas como objetos es ___. (7 letras)", "e": "Escribir rutas con barras de un solo sistema operativo."},
  {"m": "Errores, archivos y objetos", "t": "CSV", "x": "Formato de texto con datos separados por comas.\n\nEl módulo csv lee y escribe archivos CSV. csv.reader da cada fila como lista y csv.DictReader como diccionario con los nombres de las columnas. Las primeras líneas suelen ser los títulos. Cualquier hoja de cálculo abre y guarda CSV.", "u": "Intercambiar tablas con hojas de cálculo.\n\nQuieres leer un archivo exportado desde una hoja de cálculo con filas y columnas.", "p": ["Un CSV guarda datos tabulares separados por comas.", "csv.DictReader devuelve cada fila como diccionario.", "Las hojas de cálculo pueden abrir y guardar CSV."], "c": "import csv\nwith open(\"alumnos.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    escritor = csv.writer(f)\n    escritor.writerow([\"nombre\", \"nota\"])\n    escritor.writerow([\"Ana\", 9])\n    escritor.writerow([\"Luis\", 6])\n\nwith open(\"alumnos.csv\", newline=\"\", encoding=\"utf-8\") as f:\n    for fila in csv.DictReader(f):\n        print(fila[\"nombre\"], int(fila[\"nota\"]))", "h": "Escribe un CSV con alumnos y lo lee como diccionarios.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El módulo de Python para leer y escribir CSV se llama ___. (3 letras)", "e": "Olvidar convertir a número los valores leídos de un CSV."},
  {"m": "Errores, archivos y objetos", "t": "JSON en Python", "x": "Formato de texto para guardar y enviar datos estructurados.\n\nEl módulo json convierte entre diccionarios de Python y texto JSON. json.dumps(dic) devuelve texto, json.loads(texto) devuelve el diccionario; json.dump y json.load trabajan directamente con archivos. Las claves del JSON siempre son textos.", "u": "Intercambiar datos con APIs y guardar configuraciones.\n\nQuieres guardar un diccionario en un archivo en formato de intercambio estándar.", "p": ["json.dumps convierte un objeto en texto JSON.", "json.loads convierte texto JSON en objeto.", "json.dump y json.load trabajan con archivos."], "c": "import json\npersona = {\"nombre\": \"Ana\", \"edad\": 20, \"intereses\": [\"web\", \"datos\"]}\ntexto = json.dumps(persona, ensure_ascii=False, indent=2)\nprint(texto)\nvuelta = json.loads(texto)\nprint(vuelta[\"intereses\"][0])\nwith open(\"persona.json\", \"w\", encoding=\"utf-8\") as f:\n    json.dump(persona, f, ensure_ascii=False)", "h": "Convierte un diccionario en JSON, lo recupera y lo guarda en un archivo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que convierte un diccionario en texto JSON es json.___(). (5 letras: dumps)", "e": "Intentar guardar un conjunto (set) en JSON."},
  {"m": "Errores, archivos y objetos", "t": "Módulos propios", "x": "Archivos .py tuyos que se importan desde otros programas.\n\nCualquier archivo .py es un módulo. Si guardas funciones en utilidades.py, otro archivo puede hacer import utilidades o from utilidades import saludar. Python busca los módulos primero en la carpeta del programa. Evita nombres que coincidan con módulos estándar (random.py).", "u": "Dividir un proyecto en archivos organizados.\n\nQuieres guardar tus funciones en otro archivo para usarlas desde varios programas.", "p": ["Cualquier archivo .py puede importarse como módulo.", "from modulo import nombre trae solo lo necesario.", "No conviene llamar a tus módulos como los estándar."], "c": "# Guarda en utilidades.py:\n#   def saludar(nombre):\n#       return f\"Hola, {nombre}\"\n# Y en principal.py:\n#   from utilidades import saludar\n#   print(saludar(\"Ana\"))\ndef saludar(nombre):\n    return f\"Hola, {nombre}\"\nprint(saludar(\"Ana\"))", "h": "Muestra cómo guardar una función en un módulo y usarla desde otro archivo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para traer una función concreta de un módulo se escribe from módulo ___ función. (6 letras)", "e": "Nombrar un módulo propio como uno estándar y provocar conflictos."},
  {"m": "Errores, archivos y objetos", "t": "if __name__ == main", "x": "Comprobación que ejecuta código solo al correr el archivo directamente.\n\nCuando un archivo se ejecuta directamente, __name__ vale \"__main__\"; cuando se importa, vale el nombre del módulo. El bloque if __name__ == \"__main__\": permite que un archivo sirva a la vez como módulo y como programa sin ejecutar cosas al importarlo.", "u": "Separar lo que se importa de lo que se ejecuta.\n\nQuieres que cierto código se ejecute solo cuando corres el archivo, no cuando alguien lo importa.", "p": ["__name__ vale __main__ al ejecutar el archivo directamente.", "Al importar un módulo, __name__ vale el nombre del módulo.", "Evita ejecutar código al importar."], "c": "def principal():\n    print(\"Programa en marcha\")\n\nif __name__ == \"__main__\":      # solo si se ejecuta directamente\n    principal()\nprint(\"Valor de __name__:\", __name__)", "h": "Ejecuta una función principal solo cuando el archivo se corre directamente.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Al ejecutar un archivo directamente, __name__ vale \"__main___\". Escribe el valor sin comillas.", "e": "Dejar código suelto que se ejecuta al importar el módulo."},
  {"m": "Errores, archivos y objetos", "t": "Fechas con datetime", "x": "Módulo para trabajar con fechas, horas y duraciones.\n\ndatetime.now() da el momento actual. date(2026, 3, 15) crea una fecha. Restar dos fechas da un timedelta con los días de diferencia. strftime(\"%d/%m/%Y\") da formato al texto y strptime convierte un texto en fecha.", "u": "Registrar momentos, calcular plazos y edades.\n\nQuieres calcular cuántos días faltan para una fecha concreta.", "p": ["datetime.now() devuelve la fecha y hora actuales.", "Restar dos fechas devuelve un timedelta.", "strftime da formato a una fecha como texto."], "c": "from datetime import date, datetime\nhoy = date(2026, 3, 1)\nexamen = date(2026, 3, 15)\nprint((examen - hoy).days, \"días\")               # 14 días\nprint(examen.strftime(\"%d/%m/%Y\"))               # 15/03/2026\nprint(datetime.strptime(\"20/05/2026\", \"%d/%m/%Y\").year)\nprint(type(datetime.now()).__name__)", "h": "Calcula días entre fechas y convierte entre texto y fecha.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El módulo de Python para fechas y horas es ___. (8 letras)", "e": "Comparar fechas como si fueran textos."},
  {"m": "Errores, archivos y objetos", "t": "Números aleatorios con random", "x": "Módulo que genera valores al azar.\n\nrandom.randint(1, 6) da un entero entre 1 y 6 (ambos incluidos). random.choice(lista) elige un elemento, random.shuffle(lista) desordena y random.sample(lista, 3) elige varios sin repetir. random.seed(42) hace que los resultados sean reproducibles.", "u": "Crear juegos, sorteos y simulaciones.\n\nQuieres simular una tirada de dado de 1 a 6.", "p": ["randint incluye los dos extremos.", "choice elige un elemento al azar de una lista.", "seed hace reproducible la secuencia aleatoria."], "c": "import random\nrandom.seed(42)                       # resultados reproducibles\nprint(random.randint(1, 6))           # 1 a 6, ambos incluidos\nprint(random.choice([\"piedra\", \"papel\", \"tijera\"]))\ncartas = list(range(1, 6))\nrandom.shuffle(cartas)\nprint(cartas)\nprint(random.sample(range(1, 50), 3))", "h": "Simula un dado, elige al azar, desordena una lista y sortea tres números.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que da un entero al azar entre dos valores es random.___(). (7 letras)", "e": "Creer que randint no incluye el límite superior."},
  {"m": "Errores, archivos y objetos", "t": "Clases y objetos", "x": "Plantillas para crear objetos con datos y comportamientos.\n\nUna clase es el molde (Perro) y un objeto es cada ejemplar creado con él (rex = Perro()). La clase agrupa datos (atributos) y acciones (métodos). Se escribe en mayúscula inicial: class Perro:. Es la base de la programación orientada a objetos.", "u": "Modelar cosas del mundo real dentro del programa.\n\nQuieres crear muchos perros distintos a partir de una misma plantilla.", "p": ["Una clase es una plantilla y un objeto es un ejemplar suyo.", "Las clases se escriben con la primera letra en mayúscula.", "Una clase agrupa atributos y métodos."], "c": "class Perro:\n    def ladrar(self):\n        return \"¡Guau!\"\n\nrex = Perro()            # objeto 1\nluna = Perro()           # objeto 2\nprint(rex.ladrar(), luna.ladrar())\nprint(type(rex).__name__)", "h": "Define una clase Perro y crea dos objetos a partir de ella.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que define una clase es ___. (5 letras)", "e": "Confundir la clase (el molde) con el objeto (el ejemplar)."},
  {"m": "Errores, archivos y objetos", "t": "__init__ y atributos", "x": "Método especial que prepara cada objeto al crearlo.\n\n__init__(self, nombre) se ejecuta automáticamente al crear el objeto. Dentro, self.nombre = nombre guarda un atributo propio de ese objeto. self es el propio objeto y siempre es el primer parámetro de los métodos. Cada objeto tiene sus propios valores.", "u": "Guardar los datos propios de cada objeto.\n\nQuieres que cada perro creado guarde su propio nombre y edad.", "p": ["__init__ se ejecuta al crear un objeto.", "self representa al propio objeto.", "Cada objeto tiene sus propios atributos."], "c": "class Perro:\n    def __init__(self, nombre, edad):       # se ejecuta al crear el objeto\n        self.nombre = nombre                # atributos propios\n        self.edad = edad\n\nrex = Perro(\"Rex\", 3)\nluna = Perro(\"Luna\", 5)\nprint(rex.nombre, rex.edad)\nprint(luna.nombre, luna.edad)", "h": "Guarda nombre y edad propios en cada perro creado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método especial que se ejecuta al crear un objeto es ___. (8 caracteres: __init__)", "e": "Olvidar self en un método o al guardar un atributo. Falta self: debe ser self.nombre = nombre para guardarlo en el objeto."},
  {"m": "Errores, archivos y objetos", "t": "Métodos de objetos en Python", "x": "Funciones definidas dentro de una clase.\n\nUn método es una función de la clase y su primer parámetro es self. Puede leer y modificar los atributos del objeto: self.energia -= 10. Se llama con el punto: rex.correr(). Los métodos describen lo que el objeto sabe hacer.", "u": "Darle acciones a los objetos que usan sus propios datos.\n\nQuieres que un perro pueda correr y gastar energía.", "p": ["Un método es una función definida dentro de una clase.", "Su primer parámetro es self.", "Puede leer y modificar los atributos del objeto."], "c": "class Perro:\n    def __init__(self, nombre):\n        self.nombre = nombre\n        self.energia = 100\n\n    def correr(self):\n        self.energia -= 30                       # modifica su propio atributo\n        return f\"{self.nombre} corre. Energía: {self.energia}\"\n\nrex = Perro(\"Rex\")\nprint(rex.correr())\nprint(rex.correr())", "h": "Define un método que modifica la energía del propio objeto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una función definida dentro de una clase se llama ___. (6 letras: método)", "e": "Llamar a un método sin crear antes el objeto."},
  {"m": "Errores, archivos y objetos", "t": "Herencia", "x": "Mecanismo por el que una clase hereda de otra.\n\nclass Perro(Animal): hace que Perro tenga todo lo de Animal y pueda añadir o cambiar cosas. super() llama a la clase padre. Sirve para evitar repetir código común (como nombre) entre clases parecidas. Conviene usarla cuando «X es un tipo de Y».", "u": "Reutilizar código y crear variantes de una clase.\n\nQuieres que Perro y Gato reutilicen lo que tienen en común de Animal.", "p": ["Una clase hija hereda atributos y métodos de la clase padre.", "super() permite llamar al código de la clase padre.", "La herencia evita repetir código común."], "c": "class Animal:\n    def __init__(self, nombre):\n        self.nombre = nombre\n    def presentarse(self):\n        return f\"Soy {self.nombre}\"\n\nclass Perro(Animal):                    # hereda de Animal\n    def hablar(self):\n        return \"¡Guau!\"\n\nclass Gato(Animal):\n    def hablar(self):\n        return \"¡Miau!\"\n\nfor animal in [Perro(\"Rex\"), Gato(\"Misu\")]:\n    print(animal.presentarse(), animal.hablar())", "h": "Reutiliza la clase Animal en Perro y Gato, que añaden su propio sonido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En class Perro(Animal), la clase padre es ___. (6 letras)", "e": "Usar herencia cuando no existe una relación «es un tipo de»."},
  {"m": "Errores, archivos y objetos", "t": "Métodos especiales", "x": "Métodos con doble guion bajo que personalizan los objetos.\n\n__str__ define cómo se muestra el objeto con print. __len__ permite usar len(objeto), __eq__ define la igualdad y __add__ el operador +. Dan a tus clases el comportamiento natural de los tipos de Python.", "u": "Controlar cómo se muestra, compara y opera un objeto.\n\nQuieres que al imprimir un objeto aparezca un texto descriptivo y no algo como <Perro object>.", "p": ["__str__ define cómo se muestra un objeto con print.", "__len__ permite usar len() con el objeto.", "Los métodos especiales llevan doble guion bajo."], "c": "class Perro:\n    def __init__(self, nombre, edad):\n        self.nombre, self.edad = nombre, edad\n    def __str__(self):                         # cómo se muestra con print\n        return f\"{self.nombre} ({self.edad} años)\"\n    def __eq__(self, otro):                    # cómo se compara con ==\n        return self.nombre == otro.nombre\n\nrex = Perro(\"Rex\", 3)\nprint(rex)\nprint(rex == Perro(\"Rex\", 9))", "h": "Personaliza cómo se muestra y se compara un objeto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método especial que define cómo se muestra un objeto es ___. (7 caracteres: __str__)", "e": "Olvidar que __str__ debe devolver un texto."},
  {"m": "Errores, archivos y objetos", "t": "Proyecto: gestor de tareas", "x": "Programa que reúne funciones, colecciones, archivos y clases.\n\nPara cerrar Python, crea un gestor de tareas: una clase Tarea (texto, hecha), una lista de tareas, funciones para añadir, completar y mostrar, y guardado en un archivo JSON. Después puedes ampliarlo con fechas, prioridades o una interfaz web.", "u": "Practicar todo lo aprendido en un caso completo.\n\nQuieres cerrar el curso con un programa que añada, complete y guarde tareas.", "p": ["Un proyecto completo combina clases, colecciones y archivos.", "JSON permite guardar las tareas entre ejecuciones.", "Dividir el programa en funciones lo hace más claro."], "c": "import json\nclass Tarea:\n    def __init__(self, texto, hecha=False):\n        self.texto, self.hecha = texto, hecha\n    def __str__(self):\n        return (\"[x] \" if self.hecha else \"[ ] \") + self.texto\n\ntareas = [Tarea(\"Estudiar Python\"), Tarea(\"Hacer ejercicio\")]\ntareas[0].hecha = True\nfor t in tareas:\n    print(t)\ndatos = [{\"texto\": t.texto, \"hecha\": t.hecha} for t in tareas]\nwith open(\"tareas.json\", \"w\", encoding=\"utf-8\") as f:\n    json.dump(datos, f, ensure_ascii=False)\nprint(\"Guardadas:\", len(datos))", "h": "Modela tareas con una clase, las muestra y las guarda en JSON.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para cerrar el curso conviene hacer un ___ completo. (8 letras)", "e": "Escribir todo el programa en una sola función gigante."}
];
